/**
 * Heading A/B Test Hook
 * 
 * Fetches active heading variants from the backend, assigns a variant
 * to the visitor (persisted in localStorage), and returns the assigned
 * headline + subheadline for rendering.
 * 
 * Assignment is weighted and sticky: once a visitor is assigned a variant,
 * they see the same one on every visit until:
 * 1. The active variant set changes (slug fingerprint)
 * 2. The server-side version counter is bumped (admin actions)
 * 
 * Template variables:
 * - {{customerCount}} → dynamic customer count (e.g., "814,000+")
 * - {{customerCountShort}} → short format (e.g., "814K+")
 */
import { useState, useEffect, useMemo } from "react";
import { trpc } from "@/lib/trpc";
import { useCustomerCount, formatShort } from "@/components/CustomerCount";

const HEADING_VARIANT_KEY = "fluff_heading_variant";
const HEADING_VARIANT_VERSION_KEY = "fluff_heading_variant_version";
const HEADING_SERVER_VERSION_KEY = "fluff_heading_server_version";

interface HeadingVariantResult {
  /** The assigned variant slug (e.g., 'control', 'pain-relief') */
  variantSlug: string;
  /** The headline text to display */
  headline: string | null;
  /** The subheadline text (null = use page default) */
  subheadline: string | null;
  /** Whether the variant data is still loading */
  isLoading: boolean;
}

/**
 * Replace template variables in heading text with dynamic values
 */
function interpolateTemplate(text: string | null, customerCount: number): string | null {
  if (!text) return null;
  const fullCount = `${customerCount.toLocaleString('en-US')}+`;
  const shortCount = `${formatShort(customerCount)}+`;
  return text
    .replace(/\{\{customerCount\}\}/g, fullCount)
    .replace(/\{\{customerCountShort\}\}/g, shortCount);
}

export function useHeadingVariant(pageId: string): HeadingVariantResult {
  const { data: variants, isLoading } = trpc.cro.getActiveHeadingVariants.useQuery(
    { pageId },
    { staleTime: 5 * 60 * 1000 } // Cache for 5 minutes
  );

  // Check server-side version counter (lightweight, public endpoint)
  const { data: versionData } = trpc.cro.variantVersion.useQuery(undefined, {
    staleTime: 2 * 60 * 1000, // Check every 2 minutes
  });

  // Get dynamic customer count for template interpolation
  const customerCount = useCustomerCount();

  const [assignedSlug, setAssignedSlug] = useState<string | null>(() => {
    return localStorage.getItem(HEADING_VARIANT_KEY);
  });

  // Compute a version fingerprint from active variant slugs
  const variantVersion = useMemo(() => {
    if (!variants || variants.length === 0) return "";
    return variants.map(v => v.slug).sort().join(",");
  }, [variants]);

  useEffect(() => {
    if (!variants || variants.length === 0) return;

    let needsReassign = false;

    // Check 1: slug fingerprint changed (variants added/removed)
    const storedVersion = localStorage.getItem(HEADING_VARIANT_VERSION_KEY);
    if (storedVersion !== variantVersion) {
      needsReassign = true;
    }

    // Check 2: server version bumped (admin killed/paused/reactivated)
    if (versionData?.version) {
      const storedServerVersion = localStorage.getItem(HEADING_SERVER_VERSION_KEY);
      if (storedServerVersion !== String(versionData.version)) {
        needsReassign = true;
        localStorage.setItem(HEADING_SERVER_VERSION_KEY, String(versionData.version));
      }
    }

    if (needsReassign) {
      localStorage.removeItem(HEADING_VARIANT_KEY);
      setAssignedSlug(null);
    }

    const existingSlug = needsReassign ? null : localStorage.getItem(HEADING_VARIANT_KEY);

    // Check if existing assignment is still valid
    if (existingSlug) {
      const stillValid = variants.some(v => v.slug === existingSlug);
      if (stillValid) {
        setAssignedSlug(existingSlug);
        return;
      }
    }

    // Weighted random assignment (equal weights = equal split)
    const totalWeight = variants.reduce((sum, v) => sum + (v.weight ?? 1), 0);
    let random = Math.random() * totalWeight;
    let selected = variants[0];

    for (const variant of variants) {
      random -= (variant.weight ?? 1);
      if (random <= 0) {
        selected = variant;
        break;
      }
    }

    localStorage.setItem(HEADING_VARIANT_KEY, selected.slug);
    localStorage.setItem(HEADING_VARIANT_VERSION_KEY, variantVersion);
    setAssignedSlug(selected.slug);
  }, [variants, variantVersion, versionData]);

  // Find the assigned variant data
  const assignedVariant = useMemo(() => {
    if (!variants || !assignedSlug) return null;
    return variants.find(v => v.slug === assignedSlug) ?? null;
  }, [variants, assignedSlug]);

  // Interpolate template variables in the headline and subheadline
  const headline = useMemo(
    () => interpolateTemplate(assignedVariant?.headline ?? null, customerCount),
    [assignedVariant?.headline, customerCount]
  );

  const subheadline = useMemo(
    () => interpolateTemplate(assignedVariant?.subheadline ?? null, customerCount),
    [assignedVariant?.subheadline, customerCount]
  );

  return {
    variantSlug: assignedSlug || "control",
    headline,
    subheadline,
    isLoading,
  };
}
