/**
 * CRO Analytics Tracking Hook
 * 
 * Provides methods for tracking gallery interactions, heading impressions,
 * and checkout clicks. Uses a persistent visitor ID stored in localStorage.
 * 
 * Events are sent via tRPC mutations. Gallery time-spent is tracked
 * by measuring how long each slide is visible and flushing on unload.
 */
import { useCallback, useEffect, useRef } from "react";
import { trpc } from "@/lib/trpc";

// ── Visitor ID ──────────────────────────────────────────────
const VISITOR_ID_KEY = "fluff_cro_visitor_id";

function getVisitorId(): string {
  let id = localStorage.getItem(VISITOR_ID_KEY);
  if (!id) {
    id = `v_${Date.now()}_${Math.random().toString(36).slice(2, 10)}`;
    localStorage.setItem(VISITOR_ID_KEY, id);
  }
  return id;
}

// ── Device Type ─────────────────────────────────────────────
function getDeviceType(): "mobile" | "tablet" | "desktop" {
  const w = window.innerWidth;
  if (w < 768) return "mobile";
  if (w < 1024) return "tablet";
  return "desktop";
}

// ── Gallery Slide Labels ────────────────────────────────────
// Human-friendly labels matching the thumbnail indicators on the gallery
const GALLERY_SLIDE_LABELS: Record<string, string> = {
  // Special component slides
  comparison: "VS Comparison",
  "hotel-comparison": "Hotel Pricing",
  "expert-pillow": "Expert Review",
  "couple-sleep": "Couple Sleep",
  "ethical-making": "Ethical Making",
};

// Map image URLs/paths to human-friendly names based on thumbnail labels
const IMAGE_PATH_LABELS: Record<string, string> = {
  // Hero pillow image → "5-star" thumbnail label
  "MWaaoxsUftIchIcc": "Hero Pillow",
  "hero-pillow": "Hero Pillow",
  "pillow-hero": "Hero Pillow",
  // Lifestyle/tips image → "why" thumbnail label  
  "sbJxxEWpfZlzjeLo": "Sleep Tips",
  "lifestyle-sleep": "Sleep Tips",
  // Engineering detail → "3 layers" thumbnail label
  "engineering-detail": "3 Layers",
  // Washing machine → "care" thumbnail label
  "RVxCLjqishtuSISc": "Care Guide",
  "washing-machine": "Care Guide",
  // Hotel comfort packaging → "hotel" thumbnail label
  "hotel-comfort-packaging": "Hotel Quality",
};

function getGallerySlideLabel(image: string, index: number): string {
  // Check special component slides first
  if (GALLERY_SLIDE_LABELS[image]) return GALLERY_SLIDE_LABELS[image];
  
  // Try to match image URL/path to a human-friendly label
  for (const [key, label] of Object.entries(IMAGE_PATH_LABELS)) {
    if (image.includes(key)) return label;
  }
  
  // Fallback: extract filename
  const match = image.match(/\/([^/]+)\.(png|webp|jpg|jpeg)$/i);
  if (match) return match[1].replace(/-/g, " ").replace(/\b\w/g, c => c.toUpperCase());
  
  return `Slide ${index + 1}`;
}

// ── Hook ────────────────────────────────────────────────────
interface UseCroTrackingOptions {
  pageId: string;
  pagePath: string;
  galleryImages: string[];
}

export function useCroTracking({ pageId, pagePath, galleryImages }: UseCroTrackingOptions) {
  const trackEventMutation = trpc.cro.trackEvent.useMutation();

  // Track which heading variant is currently active (set by the heading A/B system)
  const activeHeadingVariantRef = useRef<string>("control");

  // Gallery time tracking: store start timestamp per slide index
  const slideStartTimeRef = useRef<number>(Date.now());
  const currentSlideRef = useRef<number>(0);
  // Accumulated time per label (in ms) — accumulated across slide changes
  const accumulatedTimeRef = useRef<Map<string, number>>(new Map());
  // Track whether we've already flushed to avoid double-sends
  const hasFlushedRef = useRef<boolean>(false);

  // ── Set active heading variant ────────────────────────────
  const setActiveHeadingVariant = useCallback((variant: string) => {
    activeHeadingVariantRef.current = variant;
  }, []);

  // ── Track Gallery Click ───────────────────────────────────
  const trackGalleryClick = useCallback((slideIndex: number) => {
    const label = getGallerySlideLabel(galleryImages[slideIndex] || "", slideIndex);
    trackEventMutation.mutate({
      visitorId: getVisitorId(),
      category: "gallery",
      action: "click",
      label,
      value: slideIndex,
      pagePath,
      pageId,
      headingVariant: activeHeadingVariantRef.current,
      deviceType: getDeviceType(),
    });
  }, [galleryImages, pagePath, pageId]);

  // ── Track Gallery Impression (when a slide becomes visible) ─
  const trackGalleryImpression = useCallback((slideIndex: number) => {
    const label = getGallerySlideLabel(galleryImages[slideIndex] || "", slideIndex);
    trackEventMutation.mutate({
      visitorId: getVisitorId(),
      category: "gallery",
      action: "impression",
      label,
      value: slideIndex,
      pagePath,
      pageId,
      headingVariant: activeHeadingVariantRef.current,
      deviceType: getDeviceType(),
    });
  }, [galleryImages, pagePath, pageId]);

  // ── Track Gallery Slide Change (for time tracking) ────────
  const onGallerySlideChange = useCallback((newIndex: number) => {
    const now = Date.now();
    const prevIndex = currentSlideRef.current;

    // Accumulate time for previous slide
    const startTime = slideStartTimeRef.current;
    if (startTime) {
      const elapsed = now - startTime;
      if (elapsed > 200) { // Ignore sub-200ms flickers
        const prevLabel = getGallerySlideLabel(galleryImages[prevIndex] || "", prevIndex);
        const existing = accumulatedTimeRef.current.get(prevLabel) || 0;
        accumulatedTimeRef.current.set(prevLabel, existing + elapsed);
      }
    }

    // Start timer for new slide
    slideStartTimeRef.current = now;
    currentSlideRef.current = newIndex;

    // Track impression for the new slide
    trackGalleryImpression(newIndex);
  }, [galleryImages, trackGalleryImpression]);

  // ── Track Heading Impression ──────────────────────────────
  const trackHeadingImpression = useCallback((variantSlug: string) => {
    trackEventMutation.mutate({
      visitorId: getVisitorId(),
      category: "heading",
      action: "impression",
      label: variantSlug,
      pagePath,
      pageId,
      headingVariant: variantSlug,
      deviceType: getDeviceType(),
    });
  }, [pagePath, pageId]);

  // ── Track Checkout Click ──────────────────────────────────
  const trackCheckoutClick = useCallback((buttonLabel: string) => {
    trackEventMutation.mutate({
      visitorId: getVisitorId(),
      category: "checkout",
      action: "checkout_click",
      label: buttonLabel,
      pagePath,
      pageId,
      headingVariant: activeHeadingVariantRef.current,
      deviceType: getDeviceType(),
    });
  }, [pagePath, pageId]);

  // ── Flush gallery time data on page unload ────────────────
  useEffect(() => {
    // Start timer for the first slide
    slideStartTimeRef.current = Date.now();
    hasFlushedRef.current = false;

    const flushTimeData = () => {
      // Prevent double-flush
      if (hasFlushedRef.current) return;
      hasFlushedRef.current = true;

      const now = Date.now();
      // Accumulate time for current slide
      const currentIdx = currentSlideRef.current;
      const startTime = slideStartTimeRef.current;
      if (startTime) {
        const elapsed = now - startTime;
        if (elapsed > 200) {
          const label = getGallerySlideLabel(galleryImages[currentIdx] || "", currentIdx);
          const existing = accumulatedTimeRef.current.get(label) || 0;
          accumulatedTimeRef.current.set(label, existing + elapsed);
        }
      }

      // Build individual events for each slide with accumulated time
      const events: Array<{
        visitorId: string;
        category: "gallery";
        action: string;
        label: string;
        value: number;
        pagePath: string;
        pageId: string;
        headingVariant: string;
        deviceType: string;
      }> = [];

      accumulatedTimeRef.current.forEach((timeMs, label) => {
        if (timeMs > 500) { // Only track if viewed for more than 500ms
          events.push({
            visitorId: getVisitorId(),
            category: "gallery",
            action: "time_spent",
            label,
            value: Math.round(timeMs),
            pagePath,
            pageId,
            headingVariant: activeHeadingVariantRef.current,
            deviceType: getDeviceType(),
          });
        }
      });

      if (events.length > 0) {
        // Use sendBeacon with individual tRPC batch format
        const url = "/api/trpc/cro.trackEventsBatch";
        const body = JSON.stringify({
          "0": { json: { events } },
        });
        if (navigator.sendBeacon) {
          navigator.sendBeacon(url, new Blob([body], { type: "application/json" }));
        } else {
          // Fallback: fire-and-forget fetch
          fetch(url, {
            method: "POST",
            body,
            headers: { "Content-Type": "application/json" },
            keepalive: true,
          }).catch(() => {});
        }
      }

      // Clear accumulated time after flush
      accumulatedTimeRef.current.clear();
    };

    const handleBeforeUnload = () => flushTimeData();
    const handleVisibilityChange = () => {
      if (document.visibilityState === "hidden") {
        flushTimeData();
      } else {
        // Reset flush flag when page becomes visible again so we can flush on next hide
        hasFlushedRef.current = false;
        slideStartTimeRef.current = Date.now();
      }
    };

    window.addEventListener("beforeunload", handleBeforeUnload);
    document.addEventListener("visibilitychange", handleVisibilityChange);

    return () => {
      window.removeEventListener("beforeunload", handleBeforeUnload);
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, [galleryImages, pagePath, pageId]);

  return {
    trackGalleryClick,
    trackGalleryImpression,
    onGallerySlideChange,
    trackHeadingImpression,
    trackCheckoutClick,
    setActiveHeadingVariant,
    getVisitorId,
  };
}
