/**
 * Shared types for the native checkout system.
 * Used across all checkout sub-components.
 */

export interface CartItem {
  name: string;
  size: "Standard" | "King";
  quantity: number;
  unitPrice: number; // dollars
  originalPrice?: number; // compare-at price
  type: "pillow" | "pillowcase" | "eyemask" | "extra-pillow" | "insurance" | "gift";
}

export interface ShippingAddress {
  name: string;
  line1: string;
  line2?: string;
  city: string;
  state: string;
  postalCode: string;
  country: string; // ISO 3166-1 alpha-2
}

export interface CheckoutState {
  step: "summary" | "shipping" | "payment" | "confirmation";
  cartItems: CartItem[];
  shippingAddress: ShippingAddress | null;
  email: string;
  currency: string;
  isProcessing: boolean;
  error: string | null;
}

/** Country option for the address form */
export interface CountryOption {
  code: string;
  name: string;
  currency: string;
  requiresState: boolean;
}

