interface OrderPopupProps {
  isOpen: boolean;
  onClose: () => void;
  onExitRecovery?: () => void; // Called when user closes checkout without completing
  selectedSize: "Standard" | "King";
  selectedQuantity: number;
  stockLevel: number;
  countdown: { days?: number; hours: number; minutes: number; seconds: number };
  hideFirstUpsell?: boolean; // Hide the first upsell (pillowcases)
  hideSecondUpsell?: boolean; // Hide the second upsell (silk eyemask)
  hideThirdUpsell?: boolean; // Hide the third upsell (extra pillow)
  /** A/B experiment: variant name (e.g., 'control' or 'no-animation') */
  experimentVariant?: string | null;
  /** A/B experiment: callback to track conversion events */
  onExperimentEvent?: (eventType: string, metadata?: Record<string, unknown>) => void;
  /** Checkout mode: 'shopify' (default) redirects to Shopify, 'native' shows inline address + Stripe payment */
  checkoutMode?: 'shopify' | 'native';
  /** Callback when native checkout payment succeeds */
  onNativePaymentComplete?: (paymentIntentId: string) => void;
  /** Render function for native checkout section (replaces Shopify CTA) */
  renderNativeCheckout?: (checkoutData: {
    totalPrice: number;
    totalOriginalPrice: number;
    totalSavings: number;
    subtotalPrice: number;
    shippingCost: number;
    insuranceCost: number;
    selectedSize: 'Standard' | 'King';
    selectedQuantity: number;
    cartItems: Array<{ name: string; size: 'Standard' | 'King'; quantity: number; unitPrice: number; originalPrice?: number; type: string }>;
    fp: (amount: number) => string;
    currencyCode: string;
    isUS: boolean;
  }) => React.ReactNode;
}

interface Warehouse {
  id: string;
  name: string;
  location: string;
  status: "checking" | "unavailable" | "available";
}

interface UserLocation {
  city: string | null;
  country: string | null;
  countryCode: string | null;
  state: string | null;
}

interface SmartUpsell {
  id: string;
  name: string;
  headline: string;
  description: string;
  whyItMakesSense: string[];
  price: number;
  originalPrice: number;
  savings: number;
  savingsPercent: number;
  image: string;
  imageSrcSet?: string;
  badge?: string;
  limitedQty?: number;
}

