/**
 * OrderProcessingLoader — 3.2s branded processing animation
 * 
 * Sits between Stripe payment confirmation and the upsell/thank-you page.
 * Creates psychological commitment and reduces buyer's remorse by showing
 * the order being "processed" through verification steps.
 * 
 * Timing:
 * - 0.0s – 1.0s: "Verifying payment..." (lock icon)
 * - 1.0s – 2.0s: "Securing your order..." (shield icon)
 * - 2.0s – 2.8s: "Confirming shipment details..." (package icon)
 * - 2.8s – 3.2s: "Order confirmed!" (green checkmark + celebration)
 * 
 * After 3.2s: calls onComplete() to advance to the upsell funnel.
 */

import { useState, useEffect, useRef } from "react";
import { Lock, Shield, Package, Check } from "lucide-react";
import FluffLogo from "@/components/FluffLogo";

interface OrderProcessingLoaderProps {
  onComplete: () => void;
  /** Optional: fire server-side confirmation during the animation */
  onConfirmPayment?: () => void;
  customerName?: string;
}

const STEPS = [
  {
    id: "verify",
    label: "Verifying payment",
    icon: Lock,
    duration: 1000,
    dots: true,
  },
  {
    id: "secure",
    label: "Securing your order",
    icon: Shield,
    duration: 1000,
    dots: true,
  },
  {
    id: "ship",
    label: "Confirming shipment details",
    icon: Package,
    duration: 800,
    dots: true,
  },
  {
    id: "done",
    label: "Order confirmed!",
    icon: Check,
    duration: 400,
    dots: false,
  },
] as const;

const TOTAL_DURATION = STEPS.reduce((sum, s) => sum + s.duration, 0); // 3200ms

export function OrderProcessingLoader({
  onComplete,
  onConfirmPayment,
  customerName,
}: OrderProcessingLoaderProps) {
  const [currentStep, setCurrentStep] = useState(0);
  const [progress, setProgress] = useState(0);
  const [showConfetti, setShowConfetti] = useState(false);
  const startTimeRef = useRef<number>(Date.now());
  const hasCalledConfirm = useRef(false);
  const hasCalledComplete = useRef(false);

  // Fire confirmPayment at the start of the animation
  useEffect(() => {
    if (!hasCalledConfirm.current && onConfirmPayment) {
      hasCalledConfirm.current = true;
      onConfirmPayment();
    }
  }, [onConfirmPayment]);

  // Animate through steps
  useEffect(() => {
    const animate = () => {
      const elapsed = Date.now() - startTimeRef.current;
      const pct = Math.min(elapsed / TOTAL_DURATION, 1);
      setProgress(pct);

      // Determine current step
      let accumulated = 0;
      for (let i = 0; i < STEPS.length; i++) {
        accumulated += STEPS[i].duration;
        if (elapsed < accumulated) {
          setCurrentStep(i);
          break;
        }
        if (i === STEPS.length - 1) {
          setCurrentStep(STEPS.length - 1);
        }
      }

      // Show confetti on final step
      if (pct >= 0.875 && !showConfetti) {
        setShowConfetti(true);
      }

      // Complete
      if (pct >= 1) {
        if (!hasCalledComplete.current) {
          hasCalledComplete.current = true;
          // Small delay after "Order confirmed!" shows
          setTimeout(() => onComplete(), 400);
        }
        return;
      }

      requestAnimationFrame(animate);
    };

    const raf = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(raf);
  }, [onComplete, showConfetti]);

  const step = STEPS[currentStep];
  const StepIcon = step.icon;
  const isDone = currentStep === STEPS.length - 1;

  return (
    <div className="mt-3">
      <div className="bg-white rounded-xl border border-gray-200 p-6 sm:p-8 text-center overflow-hidden relative">
        {/* Subtle confetti particles on completion */}
        {showConfetti && (
          <div className="absolute inset-0 pointer-events-none overflow-hidden">
            {Array.from({ length: 12 }).map((_, i) => (
              <div
                key={i}
                className="absolute w-1.5 h-1.5 rounded-full animate-[confettiFall_1.5s_ease-out_forwards]"
                style={{
                  left: `${10 + Math.random() * 80}%`,
                  top: "-5%",
                  backgroundColor: [
                    "#22c55e", "#424680", "#f5c542", "#e63946", "#2d3058",
                    "#22c55e", "#424680", "#f5c542", "#e63946", "#2d3058",
                    "#22c55e", "#424680",
                  ][i],
                  animationDelay: `${i * 0.08}s`,
                  opacity: 0.8,
                }}
              />
            ))}
          </div>
        )}

        {/* FluffCo Logo — subtle brand presence */}
        <div className="mb-5 flex justify-center opacity-60">
          <FluffLogo className="h-4 w-auto" color="#2d3058" />
        </div>

        {/* Icon container with animated ring */}
        <div className="relative w-16 h-16 mx-auto mb-5">
          {/* Spinning ring (hides on completion) */}
          {!isDone && (
            <div className="absolute inset-0 rounded-full border-2 border-gray-200">
              <div
                className="absolute inset-0 rounded-full border-2 border-transparent border-t-[#424680] animate-spin"
                style={{ animationDuration: "1s" }}
              />
            </div>
          )}

          {/* Icon center */}
          <div
            className={`absolute inset-1.5 rounded-full flex items-center justify-center transition-all duration-300 ${
              isDone
                ? "bg-green-500 scale-110"
                : "bg-gray-50"
            }`}
          >
            <StepIcon
              className={`w-6 h-6 transition-all duration-300 ${
                isDone ? "text-white" : "text-[#424680]"
              }`}
              strokeWidth={isDone ? 3 : 2}
            />
          </div>

          {/* Success pulse ring */}
          {isDone && (
            <div className="absolute inset-0 rounded-full bg-green-500/20 animate-ping" />
          )}
        </div>

        {/* Step label */}
        <div className="h-7 flex items-center justify-center">
          <p
            className={`text-sm font-medium transition-all duration-200 ${
              isDone ? "text-green-700 text-base font-semibold" : "text-gray-700"
            }`}
          >
            {step.label}
            {step.dots && <AnimatedDots />}
          </p>
        </div>

        {/* Personalized subtext */}
        {customerName && !isDone && (
          <p className="text-xs text-muted-foreground mt-1.5 opacity-70">
            Hang tight, {customerName.split(" ")[0]}
          </p>
        )}

        {isDone && (
          <p className="text-xs text-green-600 mt-1.5 font-medium animate-[fadeIn_0.3s_ease-out]">
            Everything looks great!
          </p>
        )}

        {/* Progress bar */}
        <div className="mt-5 mx-auto max-w-[200px]">
          <div className="h-1 bg-gray-100 rounded-full overflow-hidden">
            <div
              className="h-full rounded-full transition-all duration-100 ease-linear"
              style={{
                width: `${progress * 100}%`,
                background: isDone
                  ? "#22c55e"
                  : "linear-gradient(90deg, #2d3058, #424680)",
              }}
            />
          </div>
        </div>

        {/* Step indicators */}
        <div className="flex items-center justify-center gap-1.5 mt-3">
          {STEPS.map((_, i) => (
            <div
              key={i}
              className={`w-1.5 h-1.5 rounded-full transition-all duration-300 ${
                i < currentStep
                  ? "bg-green-500"
                  : i === currentStep
                  ? isDone
                    ? "bg-green-500 scale-125"
                    : "bg-[#424680] scale-125"
                  : "bg-gray-200"
              }`}
            />
          ))}
        </div>

        {/* Trust badges at bottom */}
        <div className="flex items-center justify-center gap-4 mt-5 text-[10px] text-muted-foreground">
          <span className="flex items-center gap-1">
            <Lock className="w-3 h-3" />
            256-bit Encrypted
          </span>
          <span className="flex items-center gap-1">
            <Shield className="w-3 h-3" />
            PCI Compliant
          </span>
        </div>
      </div>
    </div>
  );
}

/** Animated "..." dots */
function AnimatedDots() {
  return (
    <span className="inline-flex ml-0.5">
      <span className="animate-[dotPulse_1.4s_ease-in-out_infinite]">.</span>
      <span className="animate-[dotPulse_1.4s_ease-in-out_0.2s_infinite]">.</span>
      <span className="animate-[dotPulse_1.4s_ease-in-out_0.4s_infinite]">.</span>
    </span>
  );
}

export default OrderProcessingLoader;
