/**
 * Ruggie Logo — renders the official Ruggie 2.0 script wordmark (PNG).
 * Export name + props kept identical for backward compatibility with all imports.
 * On dark sections, pass a light `color` (e.g. "#FBF8F2" / "white") to invert the
 * dark wordmark to cream/white.
 */

interface FluffLogoProps {
  className?: string;
  color?: string;
}

export default function FluffLogo({ className = "h-7 w-auto", color = "currentColor" }: FluffLogoProps) {
  const wantsLight = color !== "currentColor" && /^(#?[eEfF]|white|cream)/.test(color.trim());
  return (
    <img
      src="/images/ruggie-logo.png"
      alt="Ruggie"
      className={className}
      style={wantsLight ? { filter: "brightness(0) invert(1)" } : undefined}
      width={500}
      height={293}
      loading="eager"
      decoding="async"
    />
  );
}
