/**
 * Reliable smooth anchor scrolling for the Ruggie funnel.
 *
 * Why a manual rAF animation instead of `scrollIntoView({behavior:'smooth'})`?
 *  - The app sets `html { scroll-behavior: smooth }` globally (for legacy hash-link
 *    pages). Layering `scrollIntoView({behavior:'smooth'})` / `scrollTo({behavior})`
 *    on top of that proved flaky (silent no-ops), which is why earlier code force-set
 *    `scroll-behavior:auto` and hard-jumped — killing the smooth effect for users.
 *  - This helper drives the scroll itself with requestAnimationFrame + easing, so it
 *    animates consistently and lets us pass an exact sticky-header offset. During the
 *    animation it sets `scroll-behavior:auto` so the per-frame `scrollTo` isn't
 *    re-animated by the global CSS, then restores it afterwards.
 *
 * Safety net: if rAF never fires (e.g. a backgrounded/throttled tab where rAF is
 * paused), a setTimeout jumps straight to the target so the link still works. When
 * rAF DID run we never hard-jump, so we never hijack a user who scrolled mid-animation.
 */

let activeRaf = 0;

const easeInOutCubic = (t: number): number =>
  t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;

/** Smoothly scroll the window so `el`'s top sits `offset` px below the viewport top. */
export function smoothScrollToEl(el: Element | null | undefined, offset = 80, duration = 560): void {
  if (!el || typeof window === "undefined") return;
  const docEl = document.documentElement;
  const startY = window.scrollY;
  const targetY = Math.max(0, (el as HTMLElement).getBoundingClientRect().top + startY - offset);
  const dist = targetY - startY;
  if (Math.abs(dist) < 2) return;

  if (activeRaf) cancelAnimationFrame(activeRaf);
  const prevBehavior = docEl.style.scrollBehavior;
  docEl.style.scrollBehavior = "auto"; // neutralize global CSS smooth during our animation

  let rafFired = false;
  let startTs = 0;
  const step = (ts: number) => {
    rafFired = true;
    if (!startTs) startTs = ts;
    const p = Math.min(1, (ts - startTs) / duration);
    window.scrollTo(0, Math.round(startY + dist * easeInOutCubic(p)));
    if (p < 1) {
      activeRaf = requestAnimationFrame(step);
    } else {
      activeRaf = 0;
      docEl.style.scrollBehavior = prevBehavior;
    }
  };
  activeRaf = requestAnimationFrame(step);

  // Safety net: if rAF is paused (background tab) it never fires — jump to target so
  // the link still works. Only acts when rAF truly never ran (never overrides a user
  // who scrolled away mid-animation).
  window.setTimeout(() => {
    if (!rafFired && Math.abs(window.scrollY - targetY) > 4) {
      if (activeRaf) cancelAnimationFrame(activeRaf);
      activeRaf = 0;
      window.scrollTo(0, targetY);
      docEl.style.scrollBehavior = prevBehavior;
    }
  }, duration + 140);
}

/** Convenience: smooth-scroll to an element by id. */
export function smoothScrollToId(id: string, offset = 80, duration = 560): void {
  if (typeof document === "undefined") return;
  smoothScrollToEl(document.getElementById(id), offset, duration);
}
