import { Toaster } from "@/components/ui/sonner";
import { TooltipProvider } from "@/components/ui/tooltip";
import NotFound from "@/pages/NotFound";
import { Route, Switch, Redirect, useLocation, Router as WouterRouter } from "wouter";
import ErrorBoundary from "./components/ErrorBoundary";
import { ThemeProvider } from "./contexts/ThemeContext";
import { LocaleProvider } from "./contexts/LocaleContext";
import { lazy, Suspense, useEffect, useRef } from "react";

// Lazy load non-critical routes for better initial page load
const SleepQuiz = lazy(() => import("@/pages/SleepQuiz"));
const DebugQuiz = lazy(() => import("@/pages/DebugQuiz"));
const DemoPage = lazy(() => import("@/pages/DemoPage"));
const LPManager = lazy(() => import('./pages/LPManager'));
const UseCasePage = lazy(() => import("./pages/UseCasePage"));
const FramedStory = lazy(() => import("./pages/FramedStory"));
const AdvertorialPage = lazy(() => import("./pages/AdvertorialPage"));
const NeckPainAdvertorial = lazy(() => import("./pages/NeckPainAdvertorial"));
const HotelExposeAdvertorial = lazy(() => import("./pages/HotelExposeAdvertorial"));
const YazBodyPodAdvertorial = lazy(() => import("./pages/hume/YazBodyPodAdvertorial"));
const AnaBodyPodAdvertorial = lazy(() => import("./pages/hume/AnaBodyPodAdvertorial"));
const CompareTopPillows = lazy(() => import("./pages/CompareTopPillows"));
const DownFeatherPillow = lazy(() => import("./pages/DownFeatherPillow"));
const CheckoutPreview = lazy(() => import("./pages/CheckoutPreview"));
const CheckoutPreviewV2 = lazy(() => import("./pages/CheckoutPreviewV2"));
const CheckoutInline = lazy(() => import("./pages/CheckoutInline"));
const UpsellDownFeather = lazy(() => import("./pages/UpsellDownFeather"));
import { ProductLandingTemplate } from "./templates/ProductLandingTemplate";
import { baseConfig } from "./config/base.config";
import { 
  getConfigBySlug, 
  downAlternativeConfig,
  restorativeAlignmentConfig,
  hotelQualityConfig,
  neckPainReliefConfig,
  sideSleeperConfig,
  valentineGiftConfig,
  mothersDayConfig,
  fathersDayConfig,
  blackFridayConfig,
  downFeatherConfig,
  fiveStarHotelComfortConfig,
  hotelPillowSecretConfig,
  neckPainConfessionConfig,
  hotelIndustryExposeConfig,
  getAllSlugs
} from "./config";

const LoadingSpinner = () => (
  <div className="min-h-screen flex items-center justify-center">
    <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-[#424680]"></div>
  </div>
);

/**
 * Landing Page Route Component
 * Renders a landing page based on the slug parameter
 */
function LandingPage({ params }: { params: { slug: string } }) {
  const config = getConfigBySlug(params.slug);
  
  if (!config) {
    return <NotFound />;
  }
  
  // Use UseCasePage for use-case category configs
  if (config.category === 'use-case') {
    return <UseCasePage config={config} />;
  }
  
  return <ProductLandingTemplate config={config} />;
}

/**
 * Locale validation: exactly two lowercase letters, a hyphen, two lowercase letters.
 * e.g., uk-en, de-de, fr-fr, au-en — prevents slugs like "valentine-gift" from matching.
 * Used inline in locale route render functions to validate the :locale param.
 */

/**
 * Helper to generate product landing routes for a given prefix.
 * When useRegex is true, the prefix is treated as a regex locale guard
 * (only matches xx-xx patterns like uk-en, de-de) to prevent page slugs
 * from accidentally matching as locales.
 */
function productRoutes(prefix: string, useRegex: boolean = false) {
  if (useRegex) {
    // Locale-prefixed routes using :locale param pattern.
    // The LocaleContext reads the locale from window.location.pathname directly,
    // so we don't need to pass params through wouter.
    // Using string-based /:locale/ patterns instead of RegExp for compatibility
    // with Manus preview bar (RegExp objects cause React error #31).
    return [
      <Route key="locale-home" path="/:locale">
        {(params) => {
          if (!params.locale || !/^[a-z]{2}-[a-z]{2}$/.test(params.locale)) return null;
          return <ProductLandingTemplate config={baseConfig} />;
        }}
      </Route>,
      <Route key="locale-da" path="/:locale/down-alternative">
        {(params) => {
          if (!params.locale || !/^[a-z]{2}-[a-z]{2}$/.test(params.locale)) return null;
          return <ProductLandingTemplate config={downAlternativeConfig} />;
        }}
      </Route>,
      <Route key="locale-ra" path="/:locale/down-pillow-restorative-alignment">
        {(params) => {
          if (!params.locale || !/^[a-z]{2}-[a-z]{2}$/.test(params.locale)) return null;
          return <ProductLandingTemplate config={restorativeAlignmentConfig} />;
        }}
      </Route>,
      <Route key="locale-hq" path="/:locale/hotel-quality-pillow">
        {(params) => {
          if (!params.locale || !/^[a-z]{2}-[a-z]{2}$/.test(params.locale)) return null;
          return <ProductLandingTemplate config={hotelQualityConfig} />;
        }}
      </Route>,
      <Route key="locale-np" path="/:locale/neck-pain-relief-pillow">
        {(params) => {
          if (!params.locale || !/^[a-z]{2}-[a-z]{2}$/.test(params.locale)) return null;
          return <ProductLandingTemplate config={neckPainReliefConfig} />;
        }}
      </Route>,
      <Route key="locale-ss" path="/:locale/side-sleeper-pillow">
        {(params) => {
          if (!params.locale || !/^[a-z]{2}-[a-z]{2}$/.test(params.locale)) return null;
          return <Suspense fallback={<LoadingSpinner />}><UseCasePage config={sideSleeperConfig} /></Suspense>;
        }}
      </Route>,
      <Route key="locale-vg" path="/:locale/valentine-gift">
        {(params) => {
          if (!params.locale || !/^[a-z]{2}-[a-z]{2}$/.test(params.locale)) return null;
          return <ProductLandingTemplate config={valentineGiftConfig} />;
        }}
      </Route>,
      <Route key="locale-md" path="/:locale/mothers-day-gift">
        {(params) => {
          if (!params.locale || !/^[a-z]{2}-[a-z]{2}$/.test(params.locale)) return null;
          return <ProductLandingTemplate config={mothersDayConfig} />;
        }}
      </Route>,
      <Route key="locale-fd" path="/:locale/fathers-day-gift">
        {(params) => {
          if (!params.locale || !/^[a-z]{2}-[a-z]{2}$/.test(params.locale)) return null;
          return <ProductLandingTemplate config={fathersDayConfig} />;
        }}
      </Route>,
      <Route key="locale-bf" path="/:locale/black-friday">
        {(params) => {
          if (!params.locale || !/^[a-z]{2}-[a-z]{2}$/.test(params.locale)) return null;
          return <ProductLandingTemplate config={blackFridayConfig} />;
        }}
      </Route>,
      <Route key="locale-df" path="/:locale/down-feather-pillow">
        {(params) => {
          if (!params.locale || !/^[a-z]{2}-[a-z]{2}$/.test(params.locale)) return null;
          return <ProductLandingTemplate config={downFeatherConfig} />;
        }}
      </Route>,
      <Route key="locale-fs" path="/:locale/5-star-hotel-comfort">
        {(params) => {
          if (!params.locale || !/^[a-z]{2}-[a-z]{2}$/.test(params.locale)) return null;
          return <Suspense fallback={<LoadingSpinner />}><FramedStory config={fiveStarHotelComfortConfig} /></Suspense>;
        }}
      </Route>,
    ];
  }

  // Default (non-locale) routes using standard string paths
  return [
    // Main / Down Alternative
    <Route key={`${prefix}-home`} path={`${prefix}/`}>
      {() => <ProductLandingTemplate config={baseConfig} />}
    </Route>,
    <Route key={`${prefix}-da`} path={`${prefix}/down-alternative`}>
      {() => <ProductLandingTemplate config={downAlternativeConfig} />}
    </Route>,
    // Restorative Alignment
    <Route key={`${prefix}-ra`} path={`${prefix}/down-pillow-restorative-alignment`}>
      {() => <ProductLandingTemplate config={restorativeAlignmentConfig} />}
    </Route>,
    // Hotel Quality
    <Route key={`${prefix}-hq`} path={`${prefix}/hotel-quality-pillow`}>
      {() => <ProductLandingTemplate config={hotelQualityConfig} />}
    </Route>,
    // Neck Pain Relief
    <Route key={`${prefix}-np`} path={`${prefix}/neck-pain-relief-pillow`}>
      {() => <ProductLandingTemplate config={neckPainReliefConfig} />}
    </Route>,
    // Side Sleeper
    <Route key={`${prefix}-ss`} path={`${prefix}/side-sleeper-pillow`}>
      {() => <Suspense fallback={<LoadingSpinner />}><UseCasePage config={sideSleeperConfig} /></Suspense>}
    </Route>,
    // Valentine's Day
    <Route key={`${prefix}-vg`} path={`${prefix}/valentine-gift`}>
      {() => <ProductLandingTemplate config={valentineGiftConfig} />}
    </Route>,
    // Mother's Day
    <Route key={`${prefix}-md`} path={`${prefix}/mothers-day-gift`}>
      {() => <ProductLandingTemplate config={mothersDayConfig} />}
    </Route>,
    // Father's Day
    <Route key={`${prefix}-fd`} path={`${prefix}/fathers-day-gift`}>
      {() => <ProductLandingTemplate config={fathersDayConfig} />}
    </Route>,
    // Black Friday
    <Route key={`${prefix}-bf`} path={`${prefix}/black-friday`}>
      {() => <ProductLandingTemplate config={blackFridayConfig} />}
    </Route>,
    // Down Feather Pillow (different product)
    <Route key={`${prefix}-df`} path={`${prefix}/down-feather-pillow`}>
      {() => <ProductLandingTemplate config={downFeatherConfig} />}
    </Route>,
    // 5-Star Hotel Comfort Framed Story
    <Route key={`${prefix}-fs`} path={`${prefix}/5-star-hotel-comfort`}>
      {() => <Suspense fallback={<LoadingSpinner />}><FramedStory config={fiveStarHotelComfortConfig} /></Suspense>}
    </Route>,
  ];
}

function Router() {
  // Meta Pixel: re-fire PageView on SPA route changes. The base snippet in index.html
  // already fires PageView on the initial full load, so we skip the first run here.
  const [location] = useLocation();
  const isFirstView = useRef(true);
  useEffect(() => {
    if (isFirstView.current) { isFirstView.current = false; return; }
    if (typeof window !== "undefined" && typeof window.fbq === "function") {
      window.fbq("track", "PageView");
    }
  }, [location]);

  // make sure to consider if you need authentication for certain routes
  return (
    <Switch>
      {/* Demo: send the bare domain to the Hume doctor advertorial (root still hosts the inherited PDP otherwise). */}
      <Route path="/">{() => <Redirect to="/i-thought-body-comp-scales-were-useless" />}</Route>

      {/* ============================================ */}
      {/* ADMIN - Must be before /:locale catch-all */}
      {/* ============================================ */}
      <Route path={"/admin"}>
        {() => <Suspense fallback={<LoadingSpinner />}><LPManager /></Suspense>}
      </Route>
      <Route path={"admin/:slug"}>
        {(params) => <LandingPage params={params} />}
      </Route>

      {/* ============================================ */}
      {/* CHECKOUT PREVIEW - Native checkout A/B test */}
      {/* ============================================ */}
      <Route path="/checkout-preview">
        {() => <Suspense fallback={<LoadingSpinner />}><CheckoutPreview /></Suspense>}
      </Route>
      <Route path="/checkout-preview-v2">
        {() => <Suspense fallback={<LoadingSpinner />}><CheckoutPreviewV2 /></Suspense>}
      </Route>
      <Route path="/checkout-inline">
        {() => <Suspense fallback={<LoadingSpinner />}><CheckoutInline /></Suspense>}
      </Route>
      <Route path="/upsell/down-feather">
        {() => <Suspense fallback={<LoadingSpinner />}><UpsellDownFeather /></Suspense>}
      </Route>
      
      {/* ============================================ */}
      {/* ADVERTORIAL ROUTES */}
      {/* ============================================ */}
      <Route path="/hotel-pillow-secret">
        {() => (
          <Suspense fallback={null}>
            <AdvertorialPage config={hotelPillowSecretConfig} />
          </Suspense>
        )}
      </Route>
      <Route path="/neck-pain-confession">
        {() => (
          <Suspense fallback={null}>
            <NeckPainAdvertorial config={neckPainConfessionConfig} />
          </Suspense>
        )}
      </Route>
      <Route path="/hotel-industry-expose">
        {() => (
          <Suspense fallback={null}>
            <HotelExposeAdvertorial config={hotelIndustryExposeConfig} />
          </Suspense>
        )}
      </Route>
      {/* ── Hume Health doctor advertorials ── */}
      {/* DOC-01 · Dr. Yaz Dominguez × Body Pod */}
      <Route path="/i-thought-body-comp-scales-were-useless">
        {() => (<Suspense fallback={null}><YazBodyPodAdvertorial /></Suspense>)}
      </Route>
      {/* DOC-03 · Ana Reisdorf, MS, RD × Body Pod (GLP-1 muscle-tracking angle) */}
      <Route path="/the-one-number-glp1-patients-track-wrong">
        {() => (<Suspense fallback={null}><AnaBodyPodAdvertorial /></Suspense>)}
      </Route>

      {/* ============================================ */}
      {/* COMPARE ROUTES */}
      {/* ============================================ */}
      <Route path="/compare/top-5-pillows">
        {() => (
          <Suspense fallback={null}>
            <CompareTopPillows />
          </Suspense>
        )}
      </Route>
      
      {/* ============================================ */}
      {/* DOWN FEATHER PILLOW - Uses ProductLandingTemplate with firmness selector */}
      {/* ============================================ */}
      <Route path="/down-feather-pillow">
        {() => <ProductLandingTemplate config={downFeatherConfig} />}
      </Route>

      {/* ============================================ */}
      {/* SLEEP QUIZ & UTILITY ROUTES */}
      {/* Must be before /:locale catch-all */}
      {/* ============================================ */}
      <Route path="/quiz">
        {() => <Suspense fallback={<LoadingSpinner />}><SleepQuiz /></Suspense>}
      </Route>
      <Route path="/debug-quiz">
        {() => <Suspense fallback={<LoadingSpinner />}><DebugQuiz /></Suspense>}
      </Route>
      <Route path="/demo">
        {() => <Suspense fallback={<LoadingSpinner />}><DemoPage /></Suspense>}
      </Route>
      <Route path={"/404"} component={NotFound} />

      {/* ============================================ */}
      {/* DEFAULT (US) ROUTES - No locale prefix */}
      {/* Must be BEFORE locale routes so explicit */}
      {/* paths like /valentine-gift match first, */}
      {/* not /:locale/ catching them as a locale. */}
      {/* ============================================ */}
      {productRoutes("")}

      {/* ============================================ */}
      {/* LOCALE-PREFIXED ROUTES (e.g., /uk-en/...) */}
      {/* Uses regex guard: only matches xx-xx format */}
      {/* (e.g., uk-en, de-de, fr-fr, au-en) */}
      {/* Prevents slugs like "valentine-gift" from */}
      {/* accidentally matching as a locale param. */}
      {/* ============================================ */}
      {productRoutes("", true)}
      
      {/* ============================================ */}
      {/* FALLBACK */}
      {/* ============================================ */}
      <Route component={NotFound} />
    </Switch>
  );
}

// NOTE: About Theme
// - First choose a default theme according to your design style (dark or light bg), than change color palette in index.css
//   to keep consistent foreground/background color across components
// - If you want to make theme switchable, pass `switchable` ThemeProvider and use `useTheme` hook

function App() {
  return (
    <ErrorBoundary>
      <ThemeProvider
        defaultTheme="light"
      >
        <LocaleProvider>
          <TooltipProvider>
            <Toaster />
            <WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, "")}>
              <Router />
            </WouterRouter>
          </TooltipProvider>
        </LocaleProvider>
      </ThemeProvider>
    </ErrorBoundary>
  );
}

export default App;
