export type PillowSize = 'Standard' | 'King';
export type UpsellType = 'single-pillow' | 'pillowcase-set' | 'silk-pillowcase-4x' | 'silk-eyemask' | null;

export interface CheckoutConfig {
  size: PillowSize;
  quantity: 1 | 2 | 4;
  upsell?: UpsellType;
  secondUpsell?: boolean; // Whether pillowcase set upsell is added
  pillowcaseQuantity?: number; // Number of pillowcase sets to add (default 1)
  silkEyemask?: boolean; // Whether silk eyemask upsell is added
  thirdUpsell?: boolean; // Whether extra pillow (third upsell) is added
  shippingInsurance?: boolean; // Whether shipping insurance is added
  // Gift items (added automatically when thresholds are met)
  giftSlippers?: boolean; // Whether free hotel slippers are unlocked
  slipperSize?: 'S/M' | 'L/XL'; // Selected slipper size (default: L/XL)
  giftLinenSpray?: boolean; // Whether free linen spray is unlocked
  // Locale-aware free shipping
  isUS?: boolean; // Whether the visitor is in the US (for free shipping code)
  subtotal?: number; // Product subtotal before shipping/insurance (for free shipping threshold)
}

interface CartItem {
  variant_id: string;
  quantity: number;
}

/**
 * Get the correct pillow variant ID based on size and quantity
 */
function getPillowVariantId(size: PillowSize, quantity: 1 | 2 | 4): string {
  const sizeKey = size.toLowerCase() as 'standard' | 'king';
  
  if (quantity === 1) {
    return PILLOW_VARIANTS[`${sizeKey}_1`];
  } else if (quantity === 2) {
    return PILLOW_VARIANTS[`${sizeKey}_2`];
  } else {
    // 4 pillows (updated variant IDs)
    return PILLOW_VARIANTS[`${sizeKey}_4`];
  }
}

/**
 * Generate a Shopify checkout URL based on the cart configuration
 */
export function generateCheckoutUrl(config: CheckoutConfig): string {
  const { size, quantity, upsell, secondUpsell = false, pillowcaseQuantity, silkEyemask = false, thirdUpsell = false, shippingInsurance = false } = config;
  const sizeKey = size.toLowerCase() as 'standard' | 'king';
  
  const cartItems: CartItem[] = [];
  let discountCode: string | null = null;
  
  // ============================================================
  // IMPORTANT: Shopify displays cart items in REVERSE order of the URL.
  // We build items in reverse display priority so that on Shopify checkout:
  //   TOP:    Main pillow → Pillowcases → Upsells → Insurance → Gifts  :BOTTOM
  // Therefore in the URL we add: gifts first → insurance → upsells → pillowcases → pillow last
  // ============================================================
  
  // 1. Free gift items (displayed last on Shopify = added first to URL)
  if (config.giftLinenSpray) {
    cartItems.push({
      variant_id: LINEN_SPRAY_VARIANT.variant_id,
      quantity: 1,
    });
  }
  
  if (config.giftSlippers) {
    const slipperSize = config.slipperSize || 'L/XL';
    cartItems.push({
      variant_id: HOTEL_SLIPPERS_VARIANTS[slipperSize],
      quantity: 1,
    });
  }
  
  // 2. Shipping insurance
  if (shippingInsurance) {
    cartItems.push({
      variant_id: SHIPPING_INSURANCE_VARIANT.variant_id,
      quantity: 1,
    });
  }
  
  // 3. Extra pillow (third upsell)
  if (thirdUpsell) {
    const singlePillowUpsellVariantId = PILLOW_VARIANTS[`${sizeKey}_1_upsell`];
    cartItems.push({
      variant_id: singlePillowUpsellVariantId,
      quantity: 1,
    });
    // No discount code needed - variants are pre-priced at $39.90/$49.90
  }
  
  // 4. Silk eyemask upsell
  if (silkEyemask) {
    cartItems.push({
      variant_id: SILK_EYEMASK_UPSELL_VARIANT.variant_id,
      quantity: 1,
    });
    // No discount code needed — eyemask is pre-priced at $29 in Shopify
  }
  
  // 5. First upsell (single pillow or legacy silk pillowcase)
  if (upsell === 'single-pillow') {
    const singlePillowUpsellVariantId = PILLOW_VARIANTS[`${sizeKey}_1_upsell`];
    cartItems.push({
      variant_id: singlePillowUpsellVariantId,
      quantity: 1,
    });
  } else if (upsell === 'silk-pillowcase-4x') {
    const silkPillowcaseVariant = SILK_PILLOWCASE_4X_VARIANTS[sizeKey];
    cartItems.push({
      variant_id: silkPillowcaseVariant.variant_id,
      quantity: 1,
    });
    discountCode = silkPillowcaseVariant.discount_code;
  }
  
  // 6. Pillowcase set upsell (with quantity support)
  // Uses NEW pre-priced product — no discount code needed
  if (secondUpsell) {
    const pillowcaseSetVariant = PILLOWCASE_SET_VARIANTS[sizeKey];
    const pcQty = pillowcaseQuantity ?? 1;
    cartItems.push({
      variant_id: pillowcaseSetVariant.variant_id,
      quantity: pcQty,
    });
    // No discount code — price is baked into the new Shopify product
  }
  
  // 7. Free pillowcase for 4x purchases
  // Uses $0 product — no discount code needed
  if (quantity === 4) {
    cartItems.push({
      variant_id: FREE_PILLOWCASE_VARIANTS[sizeKey],
      quantity: 1,
    });
  }
  
  // 8. Main pillow (displayed first on Shopify = added last to URL)
  const pillowVariantId = getPillowVariantId(size, quantity);
  cartItems.push({
    variant_id: pillowVariantId,
    quantity: 1,
  });
  
  // Build cart URL path
  const cartPath = cartItems
    .map(item => `${item.variant_id}:${item.quantity}`)
    .join(',');
  
  // Build query parameters
  const queryParams: string[] = [];
  
  // Auto-apply free shipping code for US orders under $99 (when no other discount is active)
  if (!discountCode && config.isUS !== false && config.subtotal !== undefined && config.subtotal < 99) {
    discountCode = DISCOUNT_CODES.free_shipping_us_sub99;
  }

  // Add discount code if applicable
  if (discountCode) {
    queryParams.push(`discount=${discountCode}`);
  }
  
  // Construct final URL
  const queryString = queryParams.length > 0 ? `?${queryParams.join('&')}` : '';
  return `${STORE_URL}/cart/${cartPath}${queryString}`;
}

