/**
 * Generate a Shopify checkout URL for the Down Feather Pillow.
 * Supports 1/2/4 quantity bundles with Firm/Soft firmness.
 * For 4x orders, automatically uses the "4 Pillows + Pillowcases" variant
 * (free pillowcase bonus built into the Shopify product).
 */
export function generateDownFeatherCheckoutUrl(config: DownFeatherCheckoutConfig): string {
  const {
    size,
    firmness,
    quantity,
    shippingInsurance = false,
    thirdUpsell = false,
    secondUpsell = false,
    pillowcaseQuantity,
    silkEyemask = false,
  } = config;
  const sizeKey = size.toLowerCase() as 'standard' | 'king';
  
  const cartItems: CartItem[] = [];
  let discountCode: string | null = null;
  
  // ============================================================
  // IMPORTANT: Shopify displays cart items in REVERSE order of the URL.
  // We build items in reverse display priority (same pattern as legacy).
  // ============================================================
  
  // 1. Free gift items
  if (config.giftLinenSpray) {
    cartItems.push({ variant_id: LINEN_SPRAY_VARIANT.variant_id, quantity: 1 });
  }
  if (config.giftSlippers) {
    const slipperSize = config.slipperSize || 'L/XL';
    cartItems.push({ variant_id: HOTEL_SLIPPERS_VARIANTS[slipperSize], quantity: 1 });
  }
  
  // 2. Shipping insurance
  if (shippingInsurance) {
    cartItems.push({ variant_id: SHIPPING_INSURANCE_VARIANT.variant_id, quantity: 1 });
  }
  
  // 3. Extra pillow upsell (uses down-feather-specific upsell variants)
  if (thirdUpsell) {
    const upsellKey = `${sizeKey}-${firmness}` as keyof typeof DOWN_FEATHER_UPSELL_VARIANTS;
    const upsellVariantId = DOWN_FEATHER_UPSELL_VARIANTS[upsellKey];
    if (upsellVariantId) {
      cartItems.push({ variant_id: upsellVariantId, quantity: 1 });
    }
  }
  
  // 4. Silk eyemask upsell (shared with legacy — same product)
  if (silkEyemask) {
    cartItems.push({ variant_id: SILK_EYEMASK_UPSELL_VARIANT.variant_id, quantity: 1 });
  }
  
  // 5. Pillowcase set upsell (shared with legacy — same product)
  if (secondUpsell) {
    const pillowcaseSetVariant = PILLOWCASE_SET_VARIANTS[sizeKey];
    const pcQty = pillowcaseQuantity ?? 1;
    cartItems.push({ variant_id: pillowcaseSetVariant.variant_id, quantity: pcQty });
  }
  
  // 6. Main pillow variant
  // For 4x orders, use the "4 Pillows + Pillowcases" variant (free pillowcase bonus)
  let variantKey: string;
  if (quantity === 4) {
    variantKey = `4pc-${sizeKey}-${firmness}`;
  } else {
    variantKey = `${quantity}-${sizeKey}-${firmness}`;
  }
  const variantId = DOWN_FEATHER_VARIANTS[variantKey as keyof typeof DOWN_FEATHER_VARIANTS];
  
  if (!variantId) {
    console.error(`[Down Feather] No variant found for ${variantKey}`);
    return '#';
  }
  
  cartItems.push({ variant_id: variantId, quantity: 1 });
  
  // Build cart URL path
  const cartPath = cartItems
    .map(item => `${item.variant_id}:${item.quantity}`)
    .join(',');
  
  // Build query parameters
  const queryParams: string[] = [];
  
  // Auto-apply free shipping code for US orders under $99
  if (!discountCode && config.isUS !== false && config.subtotal !== undefined && config.subtotal < 99) {
    discountCode = DISCOUNT_CODES.free_shipping_us_sub99;
  }
  
  if (discountCode) {
    queryParams.push(`discount=${discountCode}`);
  }
  
  const queryString = queryParams.length > 0 ? `?${queryParams.join('&')}` : '';
  return `${STORE_URL}/cart/${cartPath}${queryString}`;
}

