/**
 * Custom USP icons for Ruggie — single-color (currentColor), 24×24 stroke style.
 * Each uniquely represents one hero USP. Render in Brass via `text-accent`.
 */
interface IconProps {
  className?: string;
}

// "Stand to stop it" — a foot/weight pressing down onto the rug
export function StandIcon({ className = "h-5 w-5" }: IconProps) {
  return (
    <svg className={className} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={1.6} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <path d="M12 3v8" />
      <path d="m8 8 4 4 4-4" />
      <rect x="3.5" y="17.5" width="17" height="3" rx="1.5" />
    </svg>
  );
}

