import { useState, useEffect, useRef, useCallback } from "react";

export type Step = { n: number; title: string; body: string; img: string; alt: string };

const SLIDE_MS = 500; // keep in sync with the transition duration below

/** Single step card — shared by the desktop grid and the mobile carousel so they match exactly. */
export function StepCard({ step }: { step: Step }) {
  return (
    <div className="relative h-full rounded-2xl bg-background p-7 ring-1 ring-accent/20">
      <img
        src={step.img}
        alt={step.alt}
        loading="lazy"
        decoding="async"
        width={750}
        height={750}
        className="mb-5 aspect-square w-full rounded-xl object-cover"
      />
      <span className="grid h-10 w-10 place-items-center rounded-full bg-accent/12 ring-1 ring-accent/25 text-base font-bold text-accent">
        {step.n}
      </span>
      <h3 className="font-heading mt-5 text-xl font-bold text-foreground">{step.title}</h3>
      <p className="mt-2 leading-relaxed text-foreground/70">{step.body}</p>
    </div>
  );
}

/**
 * Mobile-only swipeable carousel for the "How it works" steps.
 * One card per view, animated slide, dot indicators, auto-advance (pauses on touch),
 * and SEAMLESS infinite looping via leading/trailing clones.
 *
 * Loop reset is driven by a timeout (not transitionend/rAF, which don't fire reliably
 * for off-screen elements), and a `busy` guard blocks input mid-slide so the index can
 * never overrun the clone range.
 */
export default function StepCarousel({ steps }: { steps: Step[] }) {
  const n = steps.length;
  // clones: [lastClone, ...real, firstClone] so we can loop without a visible jump
  const slides = [steps[n - 1], ...steps, steps[0]];
  const [idx, setIdx] = useState(1); // start on the first real slide
  const [animate, setAnimate] = useState(true); // off only during the instant clone snap
  const [paused, setPaused] = useState(false);
  const busy = useRef(false);
  const startX = useRef<number | null>(null);
  const real = (idx - 1 + n) % n;

  const move = useCallback((target: number) => {
    if (busy.current) return;
    busy.current = true;
    setAnimate(true);
    setIdx(target);
  }, []);

  // when we land on a clone, snap (no animation) to the matching real slide; always clear busy
  useEffect(() => {
    const t = setTimeout(() => {
      busy.current = false;
      if (idx === 0) {
        setAnimate(false);
        setIdx(n);
      } else if (idx === n + 1) {
        setAnimate(false);
        setIdx(1);
      }
    }, SLIDE_MS + 30);
    return () => clearTimeout(t);
  }, [idx, n]);

  // auto-advance; resets on every slide change; pauses while the user is touching
  useEffect(() => {
    if (paused) return;
    const t = setTimeout(() => move(idx + 1), 4500);
    return () => clearTimeout(t);
  }, [idx, paused, move]);

  return (
    <div>
      <div className="overflow-hidden">
        <div
          className={`flex ${animate ? "transition-transform duration-500 ease-out" : ""}`}
          style={{ transform: `translateX(-${idx * 100}%)` }}
          onTouchStart={(e) => {
            startX.current = e.touches[0].clientX;
            setPaused(true);
          }}
          onTouchEnd={(e) => {
            if (startX.current !== null) {
              const dx = e.changedTouches[0].clientX - startX.current;
              if (Math.abs(dx) > 40) move(idx + (dx < 0 ? 1 : -1));
            }
            startX.current = null;
            setPaused(false);
          }}
        >
          {slides.map((s, i) => (
            <div key={i} className="w-full shrink-0 px-1">
              <StepCard step={s} />
            </div>
          ))}
        </div>
      </div>

      {/* Dot indicators */}
      <div className="mt-6 flex justify-center gap-1.5">
        {steps.map((_, i) => (
          <button
            key={i}
            type="button"
            aria-label={`Go to step ${i + 1}`}
            onClick={() => move(i + 1)}
            className={`h-1.5 rounded-full transition-all ${i === real ? "w-5 bg-accent" : "w-1.5 bg-foreground/25"}`}
          />
        ))}
      </div>
    </div>
  );
}
