/**
 * useExperiment - Client-side A/B testing hook
 * 
 * Assigns the current visitor to an experiment variant and provides
 * a function to track conversion events.
 * 
 * Usage:
 *   const { variant, trackEvent, isLoading } = useExperiment("checkout-animation");
 *   // variant is "control" | "no-animation" | null
 *   // trackEvent("checkout_click") to record a conversion
 */

import { useState, useEffect, useCallback, useRef } from "react";
import { trpc } from "@/lib/trpc";

// Generate or retrieve a persistent anonymous visitor ID
function getVisitorId(): string {
  const STORAGE_KEY = "fluff_visitor_id";
  let id = localStorage.getItem(STORAGE_KEY);
  if (!id) {
    // Generate a random 16-char hex string
    const array = new Uint8Array(16);
    crypto.getRandomValues(array);
    id = Array.from(array, b => b.toString(16).padStart(2, "0")).join("");
    localStorage.setItem(STORAGE_KEY, id);
  }
  return id;
}

export function useExperiment(experimentSlug: string) {
  const [variant, setVariant] = useState<string | null>(null);
  const [experimentId, setExperimentId] = useState<number | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const assignedRef = useRef(false);
  const visitorIdRef = useRef<string>("");

  const assignMutation = trpc.experiments.assign.useMutation();
  const trackMutation = trpc.experiments.trackEvent.useMutation();

  useEffect(() => {
    if (assignedRef.current) return;
    assignedRef.current = true;

    const visitorId = getVisitorId();
    visitorIdRef.current = visitorId;

    assignMutation.mutate(
      {
        visitorId,
        experimentSlug,
        pagePath: window.location.pathname,
      },
      {
        onSuccess: (data) => {
          setVariant(data.variant);
          setExperimentId(data.experimentId);
          setIsLoading(false);
        },
        onError: () => {
          // On error, default to control (show animation)
          setVariant("control");
          setIsLoading(false);
        },
      }
    );
  }, [experimentSlug]);

  const trackEvent = useCallback(
    (eventType: string, metadata?: Record<string, unknown>) => {
      if (!visitorIdRef.current) return;
      trackMutation.mutate({
        visitorId: visitorIdRef.current,
        experimentSlug,
        eventType,
        metadata: metadata ? JSON.stringify(metadata) : undefined,
        pagePath: window.location.pathname,
      });
    },
    [experimentSlug]
  );

  return {
    variant,
    experimentId,
    isLoading,
    trackEvent,
    visitorId: visitorIdRef.current,
  };
}
