// PressLogos — infinite horizontal marquee of "as seen on" press logos.
// Renders real press SVGs as <img>, tinted toward onyx and dialed back on the
// Bone background so they read as a quiet trust strip, not a billboard.
// The row loops seamlessly via a CSS keyframe (two duplicated tracks) and fades
// out at both edges with a mask so logos slide in/out instead of hard-cutting.

interface PressLogosProps {
  // Kept for backward compatibility with the advertorial/comparison pages that
  // still pass a background color. The marquee only uses it to decide tint.
  backgroundColor?: string;
}

// Easy to extend — drop a new { src, alt } in and it flows into the loop.
const LOGOS = [
  { src: "/images/press/gma.svg", alt: "Good Morning America" },
  { src: "/images/press/today.svg", alt: "Today" },
  { src: "/images/press/ellen.svg", alt: "Ellen" },
  { src: "/images/press/hypebeast.svg", alt: "Hypebeast" },
];

const PressLogos = ({ backgroundColor }: PressLogosProps) => {
  // On the Ruggie LP (Bone bg) we tint logos toward onyx. The shared advertorial
  // pages pass a dark indigo bg — there we invert to white so they stay legible.
  const isDarkBg = !!backgroundColor && /424680|2d3a5c|2d3058/.test(backgroundColor);
  const tint = isDarkBg ? "invert brightness-0" : "brightness-0";

  // Two identical tracks sit side by side; the wrapper slides left by exactly one
  // track width and resets, so the seam is invisible. We render the 4 logos a few
  // times per track so even narrow viewports never show a gap.
  const fadeMask =
    "linear-gradient(to right, transparent, black 8%, black 92%, transparent)";

  const track = (key: string) => (
    <div
      key={key}
      aria-hidden={key === "b"}
      className="flex shrink-0 items-center gap-x-10 pr-10 sm:gap-x-14 sm:pr-14 lg:gap-x-20 lg:pr-20"
    >
      {[...LOGOS, ...LOGOS, ...LOGOS].map((logo, i) => (
        <img
          key={`${key}-${logo.src}-${i}`}
          src={logo.src}
          alt={key === "a" ? logo.alt : ""}
          loading="lazy"
          decoding="async"
          className={`h-[1.2rem] sm:h-[1.4rem] lg:h-[1.6rem] w-auto opacity-60 ${tint}`}
        />
      ))}
    </div>
  );

  return (
    <div className="w-full py-6 lg:py-8">
      <div
        className="flex w-full overflow-hidden"
        style={{
          WebkitMaskImage: fadeMask,
          maskImage: fadeMask,
        }}
      >
        {/* .animate-marquee (defined in index.css, built for press logos) slides the
            track left by exactly one set width (-50%) and loops, so two identical
            tracks read as one endless row. Pauses on hover. */}
        <div
          className="flex w-max animate-marquee items-center motion-reduce:animate-none"
          onMouseEnter={(e) => { e.currentTarget.style.animationPlayState = "paused"; }}
          onMouseLeave={(e) => { e.currentTarget.style.animationPlayState = "running"; }}
        >
          {track("a")}
          {track("b")}
        </div>
      </div>
    </div>
  );
};

export default PressLogos;
