/**
 * MiniReviewGallery — the shared, editorial mini-review slideshow.
 *
 * Extracted from the (loved) Ruggie Reasons hero so the SAME component can power both
 * the reasons/article hero AND the PDP buy-box (replacing the old RecentReviews design).
 *
 * One real review per slide, brass 5-star row, prev/next arrows + progress dots, auto-advance
 * every 5s (pauses on hover/focus), gentle fade-up transition. The "4.8 ★ · 789 reviews"
 * summary is always present and prominent in the header row.
 *
 * Real reviews only (FTC). Defaults to the 6 verified testimonials in base.config; pass a
 * `reviews` array to override. Styled entirely with Onyx & Brass semantic Tailwind tokens.
 */
import { useState, useEffect, useRef } from "react";
import { Star, ChevronLeft, ChevronRight } from "lucide-react";
import { baseConfig } from "@/config/base.config";

const BRASS = "#B08D57";

export interface MiniReview {
  text: string;
  author: string;
  location?: string;
}

/** The 6 real, verified Ruggie testimonials (Chloe O., Meredith, Tom, Marshall, K. Malone, Zack Franklin). */
export const BASE_MINI_REVIEWS: MiniReview[] = baseConfig.testimonials.testimonials.map((t) => ({
  text: t.content,
  author: t.name,
  location: t.location || "Verified Buyer",
}));

interface MiniReviewGalleryProps {
  /** Override the reviews (real reviews only). Defaults to base.config's 6 verified testimonials. */
  reviews?: MiniReview[];
  /** Aggregate rating shown in the summary chip. */
  rating?: string;
  /** Aggregate review count shown in the summary chip. */
  reviewCount?: string;
  /** Extra classes for the outer card. */
  className?: string;
  /** Auto-advance interval in ms (default 5000). */
  intervalMs?: number;
}

export default function MiniReviewGallery({
  reviews = BASE_MINI_REVIEWS,
  rating = "4.8",
  reviewCount = "789 reviews",
  className = "",
  intervalMs = 5000,
}: MiniReviewGalleryProps) {
  const n = reviews.length;
  const [index, setIndex] = useState(0);
  const [paused, setPaused] = useState(false);
  const go = (d: number) => setIndex((p) => (p + d + n) % n);

  // Auto-advance; resets the clock on every slide change; pauses on hover/focus.
  useEffect(() => {
    if (paused || n <= 1) return;
    const t = setTimeout(() => setIndex((p) => (p + 1) % n), intervalMs);
    return () => clearTimeout(t);
  }, [index, paused, n, intervalMs]);

  const current = reviews[index];
  if (!current) return null;

  return (
    <div
      className={`w-full rounded-xl border border-border bg-card shadow-sm ${className}`}
      onMouseEnter={() => setPaused(true)}
      onMouseLeave={() => setPaused(false)}
      onFocusCapture={() => setPaused(true)}
      onBlurCapture={() => setPaused(false)}
    >
      {/* Header: label + prominent aggregate summary */}
      <div className="flex items-center justify-between gap-2 px-4 pt-3">
        <span className="text-[10px] font-semibold uppercase tracking-[0.18em] text-muted-foreground">
          Recent reviews
        </span>
        <span className="inline-flex items-center gap-1.5 rounded-full border border-border bg-background/60 px-2 py-0.5">
          <Star className="h-3 w-3" style={{ fill: BRASS, color: BRASS }} strokeWidth={0} />
          <span className="text-[11px] font-bold text-foreground">{rating}</span>
          <span className="text-[11px] text-muted-foreground">· {reviewCount}</span>
        </span>
      </div>

      {/* Slide */}
      <div className="flex items-stretch gap-2 px-3 pb-3 pt-2">
        <button
          type="button"
          onClick={() => go(-1)}
          aria-label="Previous review"
          className="my-auto grid h-7 w-7 shrink-0 place-items-center rounded-full border border-border bg-card text-muted-foreground shadow-sm transition-colors hover:bg-secondary hover:text-foreground"
        >
          <ChevronLeft className="h-3.5 w-3.5" />
        </button>

        <div className="min-w-0 flex-1 px-1" key={index}>
          <figure className="animate-[fadeInUp_0.3s_ease-out_both]">
            <div className="mb-1 flex items-center gap-0.5">
              {Array.from({ length: 5 }).map((_, i) => (
                <Star key={i} className="h-3 w-3" style={{ fill: BRASS, color: BRASS }} strokeWidth={0} />
              ))}
            </div>
            <blockquote className="line-clamp-3 text-[13px] leading-snug text-foreground/80">
              "{current.text}"
            </blockquote>
            <figcaption className="mt-1.5 text-[11px] text-muted-foreground">
              <span className="font-medium text-foreground/70">{current.author}</span>
              {current.location ? <> · {current.location}</> : null}
            </figcaption>
          </figure>
        </div>

        <button
          type="button"
          onClick={() => go(1)}
          aria-label="Next review"
          className="my-auto grid h-7 w-7 shrink-0 place-items-center rounded-full border border-border bg-card text-muted-foreground shadow-sm transition-colors hover:bg-secondary hover:text-foreground"
        >
          <ChevronRight className="h-3.5 w-3.5" />
        </button>
      </div>

      {/* Progress dots */}
      {n > 1 && (
        <div className="flex justify-center gap-1 pb-3">
          {reviews.map((_, idx) => (
            <button
              key={idx}
              type="button"
              onClick={() => setIndex(idx)}
              aria-label={`Go to review ${idx + 1}`}
              className={`h-1.5 rounded-full transition-all ${idx === index ? "w-4" : "w-1.5 bg-muted-foreground/25"}`}
              style={idx === index ? { backgroundColor: BRASS } : undefined}
            />
          ))}
        </div>
      )}
    </div>
  );
}
