/* ─── Address Autocomplete via Server-Side tRPC Proxy ─── */
interface AddressPrediction {
  description: string;
  placeId: string;
  mainText: string;
  secondaryText: string;
}

function useAddressAutocomplete(
  countryCode: string,
  onPlaceSelected: (place: {
    line1: string;
    city: string;
    state: string;
    postalCode: string;
    country: string;
  }) => void
) {
  const [query, setQuery] = useState("");
  const [predictions, setPredictions] = useState<AddressPrediction[]>([]);
  const [showDropdown, setShowDropdown] = useState(false);
  const [sessionToken] = useState(() => crypto.randomUUID());
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const callbackRef = useRef(onPlaceSelected);
  callbackRef.current = onPlaceSelected;

  // Fetch predictions when query changes
  const fetchPredictions = useCallback(async (input: string) => {
    if (input.length < 3) {
      setPredictions([]);
      setShowDropdown(false);
      return;
    }
    try {
      const batchInput = JSON.stringify({
        "0": { json: { input, country: countryCode, sessionToken } }
      });
      const res = await fetch(
        `/api/trpc/checkout.addressAutocomplete?batch=1&input=${encodeURIComponent(batchInput)}`
      );
      const json = await res.json();
      const preds = json?.[0]?.result?.data?.json?.predictions || [];
      setPredictions(preds);
      setShowDropdown(preds.length > 0);
    } catch (err) {
      console.warn("[AddressAutocomplete] Failed to fetch predictions:", err);
      setPredictions([]);
    }
  }, [countryCode, sessionToken]);

  const onInputChange = useCallback((value: string) => {
    setQuery(value);
    if (debounceRef.current) clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(() => fetchPredictions(value), 300);
  }, [fetchPredictions]);

  const selectPrediction = useCallback(async (prediction: AddressPrediction) => {
    setShowDropdown(false);
    setQuery(prediction.mainText);
    try {
      const batchInput = JSON.stringify({
        "0": { json: { placeId: prediction.placeId, sessionToken } }
      });
      const res = await fetch(
        `/api/trpc/checkout.placeDetails?batch=1&input=${encodeURIComponent(batchInput)}`
      );
      const json = await res.json();
      const details = json?.[0]?.result?.data?.json;
      if (details) {
        callbackRef.current(details);
      }
    } catch (err) {
      console.warn("[AddressAutocomplete] Failed to fetch place details:", err);
    }
  }, [sessionToken]);

  const dismiss = useCallback(() => {
    setTimeout(() => setShowDropdown(false), 200);
  }, []);

  return { query, predictions, showDropdown, onInputChange, selectPrediction, dismiss, setQuery, setShowDropdown };
}

