/* ─── Compact Address Form ─── */
function CompactAddressForm({
  address,
  email,
  onAddressChange,
  onEmailChange,
  detectedCountryCode,
  errors = {},
  onCountryChange,
  onClearError,
}: {
  address: ShippingAddress | null;
  email: string;
  onAddressChange: (a: ShippingAddress) => void;
  onEmailChange: (e: string) => void;
  detectedCountryCode?: string;
  errors?: Record<string, string>;
  onCountryChange?: (c: CountryOption) => void;
  onClearError?: (field: string) => void;
}) {
  const [countryCode, setCountryCode] = useState(
    address?.country || detectedCountryCode || "US"
  );

  const country = useMemo(
    () => SUPPORTED_COUNTRIES.find((c) => c.code === countryCode) || SUPPORTED_COUNTRIES[0],
    [countryCode]
  );

  const stateOptions = useMemo(() => {
    switch (countryCode) {
      case "US": return US_STATES;
      case "CA": return CA_PROVINCES;
      case "AU": return AU_STATES;
      default: return [];
    }
  }, [countryCode]);

  useEffect(() => {
    if (detectedCountryCode && !address?.country) {
      setCountryCode(detectedCountryCode);
    }
  }, [detectedCountryCode, address?.country]);

  useEffect(() => {
    onCountryChange?.(country);
  }, [country, onCountryChange]);

  const update = useCallback(
    (field: keyof ShippingAddress, value: string) => {
      onAddressChange({
        name: address?.name || "",
        line1: address?.line1 || "",
        line2: address?.line2 || "",
        city: address?.city || "",
        state: address?.state || "",
        postalCode: address?.postalCode || "",
        country: countryCode,
        ...address,
        [field]: value,
      });
    },
    [address, countryCode, onAddressChange]
  );

  // Google Places autocomplete callback
  const handlePlaceSelected = useCallback(
    (place: { line1: string; city: string; state: string; postalCode: string; country: string }) => {
      onAddressChange({
        name: address?.name || "",
        line1: place.line1,
        line2: address?.line2 || "",
        city: place.city,
        state: place.state,
        postalCode: place.postalCode,
        country: place.country || countryCode,
      });
      onClearError?.("line1");
      onClearError?.("city");
      onClearError?.("state");
      onClearError?.("postalCode");
    },
    [address?.name, address?.line2, countryCode, onAddressChange, onClearError]
  );

  // Address autocomplete via server-side proxy
  const autocomplete = useAddressAutocomplete(countryCode, handlePlaceSelected);

  const handleCountrySwitch = (code: string) => {
    setCountryCode(code);
    onAddressChange({
      name: address?.name || "",
      line1: address?.line1 || "",
      line2: address?.line2 || "",
      city: address?.city || "",
      state: "",
      postalCode: address?.postalCode || "",
      country: code,
    });
  };

  // Compact input style
  const inputCls = (field: string) =>
    `w-full px-3 py-2.5 rounded-md border text-[16px] sm:text-sm transition-colors outline-none focus:ring-1 focus:ring-[#424680]/40 ${
      errors[field]
        ? "border-red-400 bg-red-50/50"
        : "border-gray-200 bg-white hover:border-gray-300 focus:border-[#424680]"
    }`;

  const selectCls = (field: string) =>
    `${inputCls(field)} appearance-none pr-8 cursor-pointer`;

  return (
    <div className="space-y-2.5">
      {/* Email */}
      <div>
        <input
          type="email"
          value={email}
          onChange={(e) => { onEmailChange(e.target.value); onClearError?.("email"); }}
          placeholder="Email"
          className={inputCls("email")}
          autoComplete="email"
          inputMode="email"
          name="email"
          id="checkout-email"
        />
        {errors.email && <p className="text-[11px] text-red-500 mt-0.5">{errors.email}</p>}
      </div>

      {/* Country */}
      <div className="relative">
        <select
          value={countryCode}
          onChange={(e) => handleCountrySwitch(e.target.value)}
          className={selectCls("country")}
          autoComplete="country"
          name="country"
          id="checkout-country"
        >
          {SUPPORTED_COUNTRIES.map((c) => (
            <option key={c.code} value={c.code}>{c.name}</option>
          ))}
        </select>
        <ChevronDown className="absolute right-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-gray-400 pointer-events-none" />
      </div>

      {/* Name */}
      <div>
        <input
          type="text"
          value={address?.name || ""}
          onChange={(e) => { update("name", e.target.value); onClearError?.("name"); }}
          placeholder="Full name"
          className={inputCls("name")}
          autoComplete="name"
          name="name"
          id="checkout-name"
        />
        {errors.name && <p className="text-[11px] text-red-500 mt-0.5">{errors.name}</p>}
      </div>

      {/* Address line 1 — with server-side Google Places autocomplete */}
      <div className="relative">
        <input
          type="text"
          value={address?.line1 || ""}
          onChange={(e) => {
            const val = e.target.value;
            update("line1", val);
            autocomplete.onInputChange(val);
            onClearError?.("line1");
          }}
          onFocus={() => {
            if (autocomplete.predictions.length > 0) autocomplete.setShowDropdown(true);
          }}
          onBlur={autocomplete.dismiss}
          placeholder="Start typing your address..."
          className={inputCls("line1")}
          autoComplete="off"
          name="address"
          id="checkout-address"
          role="combobox"
          aria-expanded={autocomplete.showDropdown}
          aria-autocomplete="list"
          aria-controls="address-suggestions"
        />
        {/* Autocomplete dropdown */}
        {autocomplete.showDropdown && autocomplete.predictions.length > 0 && (
          <div
            id="address-suggestions"
            className="absolute z-[9999] left-0 right-0 top-full mt-1 bg-white border border-gray-200 rounded-md shadow-lg max-h-[200px] overflow-y-auto"
            role="listbox"
          >
            {autocomplete.predictions.map((pred, idx) => (
              <button
                key={pred.placeId}
                type="button"
                className="w-full text-left px-3 py-2.5 hover:bg-gray-50 border-b border-gray-100 last:border-b-0 transition-colors cursor-pointer"
                onMouseDown={(e) => e.preventDefault()}
                onClick={() => autocomplete.selectPrediction(pred)}
                role="option"
                aria-selected={false}
              >
                <span className="text-sm font-medium text-gray-900">{pred.mainText}</span>
                {pred.secondaryText && (
                  <span className="text-xs text-gray-500 ml-1">{pred.secondaryText}</span>
                )}
              </button>
            ))}
          </div>
        )}
        {errors.line1 && <p className="text-[11px] text-red-500 mt-0.5">{errors.line1}</p>}
      </div>

      {/* Address line 2 */}
      <input
        type="text"
        value={address?.line2 || ""}
        onChange={(e) => update("line2", e.target.value)}
        placeholder="Apartment, suite, etc. (optional)"
        className={inputCls("line2")}
        autoComplete="address-line2"
        name="address-line2"
        id="checkout-address2"
      />

      {/* City + State row */}
      <div className="grid grid-cols-2 gap-2">
        <div>
          <input
            type="text"
            value={address?.city || ""}
            onChange={(e) => { update("city", e.target.value); onClearError?.("city"); }}
            placeholder="City"
            className={inputCls("city")}
            autoComplete="address-level2"
            name="address-level2"
            id="checkout-city"
          />
          {errors.city && <p className="text-[11px] text-red-500 mt-0.5">{errors.city}</p>}
        </div>
        {country.requiresState && stateOptions.length > 0 ? (
          <div>
            <div className="relative">
              <select
                value={address?.state || ""}
                onChange={(e) => { update("state", e.target.value); onClearError?.("state"); }}
                className={selectCls("state")}
                autoComplete="address-level1"
                name="address-level1"
                id="checkout-state"
              >
                <option value="">{countryCode === "CA" ? "Province" : "State"}</option>
                {stateOptions.map((s) => (
                  <option key={s.code} value={s.code}>{s.name}</option>
                ))}
              </select>
              <ChevronDown className="absolute right-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-gray-400 pointer-events-none" />
            </div>
            {errors.state && <p className="text-[11px] text-red-500 mt-0.5">{errors.state}</p>}
          </div>
        ) : country.requiresState ? (
          <div>
            <input
              type="text"
              value={address?.state || ""}
              onChange={(e) => update("state", e.target.value)}
              placeholder="State / Region"
              className={inputCls("state")}
              autoComplete="address-level1"
              name="address-level1"
              id="checkout-state"
            />
            {errors.state && <p className="text-[11px] text-red-500 mt-0.5">{errors.state}</p>}
          </div>
        ) : (
          <input
            type="text"
            value={address?.state || ""}
            onChange={(e) => update("state", e.target.value)}
            placeholder="Region (optional)"
            className={inputCls("state")}
            autoComplete="address-level1"
            name="address-level1"
            id="checkout-state"
          />
        )}
      </div>

      {/* Postal code */}
      <div className="max-w-[180px]">
        <input
          type="text"
          value={address?.postalCode || ""}
          onChange={(e) => { update("postalCode", e.target.value); onClearError?.("postalCode"); }}
          placeholder={countryCode === "US" ? "ZIP code" : "Postal code"}
          className={inputCls("postalCode")}
          autoComplete="postal-code"
          name="postal-code"
          id="checkout-zip"
          inputMode="text"
        />
        {errors.postalCode && <p className="text-[11px] text-red-500 mt-0.5">{errors.postalCode}</p>}
      </div>
    </div>
  );
}

/* ─── Payment Form (inside Elements provider) ─── */
function UnifiedPaymentForm({
  onPaymentSuccess,
  onPaymentError,
  isProcessing,
  setIsProcessing,
  totalAmount,
  customerEmail,
  onExpressReady,
}: {
  onPaymentSuccess: (id: string) => void;
  onPaymentError: (err: string) => void;
  isProcessing: boolean;
  setIsProcessing: (v: boolean) => void;
  totalAmount: string;
  customerEmail: string;
  onExpressReady?: (available: boolean) => void;
}) {
  const stripe = useStripe();
  const elements = useElements();
  const [paymentReady, setPaymentReady] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [expressAvailable, setExpressAvailable] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!stripe || !elements) return;

    setIsProcessing(true);
    setErrorMessage(null);

    // FB Pixel: Purchase attempt
    trackFBEvent("Purchase", {
      content_type: "product",
      value: parseFloat(totalAmount.replace(/[^0-9.]/g, "")) || 0,
      currency: "USD",
    });

    try {
      const { error, paymentIntent } = await stripe.confirmPayment({
        elements,
        confirmParams: {
          return_url: `${window.location.origin}/checkout/confirmation`,
          receipt_email: customerEmail,
        },
        redirect: "if_required",
      });

      if (error) {
        const msg =
          error.type === "card_error" || error.type === "validation_error"
            ? error.message || "Payment failed"
            : "An unexpected error occurred. Please try again.";
        setErrorMessage(msg);
        onPaymentError(msg);
      } else if (paymentIntent?.status === "succeeded") {
        onPaymentSuccess(paymentIntent.id);
      }
    } catch (err: any) {
      const msg = err.message || "Payment processing failed";
      setErrorMessage(msg);
      onPaymentError(msg);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleExpressConfirm = async () => {
    if (!stripe || !elements) return;
    setIsProcessing(true);

    // FB Pixel: Purchase via express
    trackFBEvent("Purchase", {
      content_type: "product",
      value: parseFloat(totalAmount.replace(/[^0-9.]/g, "")) || 0,
      currency: "USD",
    });

    try {
      const { error, paymentIntent } = await stripe.confirmPayment({
        elements,
        confirmParams: {
          return_url: `${window.location.origin}/checkout/confirmation`,
        },
        redirect: "if_required",
      });
      if (error) {
        onPaymentError(error.message || "Express payment failed");
      } else if (paymentIntent?.status === "succeeded") {
        onPaymentSuccess(paymentIntent.id);
      }
    } catch (err: any) {
      onPaymentError(err.message || "Express payment failed");
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-3">
      {/* Express Checkout (Apple Pay / Google Pay / Link) — prominent at top */}
      <div className="mb-1">
        <ExpressCheckoutElement
          onConfirm={handleExpressConfirm}
          onReady={(e) => {
            const available = e.availablePaymentMethods != null &&
              Object.values(e.availablePaymentMethods).some(Boolean);
            setExpressAvailable(available);
            onExpressReady?.(available);
          }}
          options={{
            buttonType: { applePay: "buy", googlePay: "buy" },
            buttonTheme: { applePay: "black", googlePay: "black" },
            layout: { maxColumns: 3, maxRows: 2 },
          }}
        />
      </div>

      {/* Divider between express and card */}
      {expressAvailable && (
        <div className="flex items-center gap-3 py-1">
          <div className="flex-1 h-px bg-gray-200" />
          <span className="text-[11px] text-muted-foreground uppercase tracking-wider font-medium">
            Or pay with card
          </span>
          <div className="flex-1 h-px bg-gray-200" />
        </div>
      )}

      {/* Stripe Payment Element — inline, compact */}
      <PaymentElement
        onReady={() => setPaymentReady(true)}
        options={{
          layout: { type: "tabs" },
          business: { name: "FluffCo" },
        }}
      />

      {/* Error message */}
      {errorMessage && (
        <div className="flex items-start gap-2 p-2.5 rounded-md bg-red-50 border border-red-200">
          <AlertCircle className="w-3.5 h-3.5 text-red-500 flex-shrink-0 mt-0.5" />
          <p className="text-xs text-red-700">{errorMessage}</p>
        </div>
      )}

      {/* Pay CTA */}
      <button
        type="submit"
        disabled={!stripe || !elements || isProcessing || !paymentReady}
        className={`w-full bg-[#e63946] hover:bg-[#d62839] text-white font-semibold py-3.5 rounded-full text-base transition-all flex items-center justify-center gap-2 ${
          isProcessing || !paymentReady
            ? "opacity-80 cursor-wait"
            : "hover:shadow-lg hover:shadow-red-200/50 active:scale-[0.98]"
        }`}
      >
        {isProcessing ? (
          <>
            <svg
              className="animate-spin h-4 w-4 text-white"
              xmlns="http://www.w3.org/2000/svg"
              fill="none"
              viewBox="0 0 24 24"
            >
              <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
              <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z" />
            </svg>
            <span>Processing...</span>
          </>
        ) : (
          <>
            <Lock className="w-4 h-4" />
            Complete Order — {totalAmount}
          </>
        )}
      </button>

      {/* Minimal trust line */}
      <div className="flex items-center justify-center gap-4 text-[10px] text-muted-foreground pt-1">
        <span className="flex items-center gap-1">
          <Lock className="w-3 h-3" />
          256-bit SSL
        </span>
        <span className="flex items-center gap-1">
          <Shield className="w-3 h-3" />
          Safe Checkout
        </span>
      </div>
    </form>
  );
}

/* ─── Post-Purchase Funnel (Multi-Step Upsell State Machine) ─── */
type FunnelStep = "upsell_1" | "downsell_1" | "confirmation";

function PostPurchaseView({
  email,
  paymentIntentId,
  totalAmount,
  customerName,
  fp,
  onClose,
}: {
  email: string;
  paymentIntentId: string;
  totalAmount: string;
  customerName: string;
  fp: (amount: number) => string;
  onClose?: () => void;
}) {
  const [funnelStep, setFunnelStep] = useState<FunnelStep>("upsell_1");
  const [isUpsellProcessing, setIsUpsellProcessing] = useState(false);
  const [acceptedUpsells, setAcceptedUpsells] = useState<string[]>([]);
  const [upsellTotal, setUpsellTotal] = useState(0);
  const firstName = customerName?.split(" ")[0] || "there";

  // Server mutations
  const confirmMutation = trpc.checkout.confirmPayment.useMutation();
  const declineUpsellMutation = trpc.checkout.declineUpsell.useMutation();
  const acceptUpsellMutation = trpc.checkout.acceptUpsell.useMutation();

  // On mount: confirm payment to set up delayed Shopify fulfillment
  useEffect(() => {
    confirmMutation.mutate({ paymentIntentId });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [paymentIntentId]);

  // Accept primary upsell
  const handleAcceptUpsell1 = async () => {
    setIsUpsellProcessing(true);
    try {
      await acceptUpsellMutation.mutateAsync({
        paymentIntentId,
        upsellItems: [
          {
            name: "Complete Sleep System",
            variantId: "0", // TODO: Replace with real Shopify variant ID
            quantity: 1,
            unitPrice: 29.90,
            size: "Standard" as const,
            type: "upsell",
          },
        ],
      });
      setAcceptedUpsells(prev => [...prev, "Complete Sleep System"]);
      setUpsellTotal(prev => prev + 29.90);
    } catch (err) {
      console.error("[Upsell] Failed:", err);
    } finally {
      setIsUpsellProcessing(false);
      setFunnelStep("confirmation");
    }
  };

  // Decline primary → show downsell
  const handleDeclineUpsell1 = () => {
    setFunnelStep("downsell_1");
  };

  // Accept downsell
  const handleAcceptDownsell = async () => {
    setIsUpsellProcessing(true);
    try {
      await acceptUpsellMutation.mutateAsync({
        paymentIntentId,
        upsellItems: [
          {
            name: "Premium Silk Pillowcases (2-Pack)",
            variantId: "0", // TODO: Replace with real Shopify variant ID
            quantity: 1,
            unitPrice: 14.95,
            size: "Standard" as const,
            type: "upsell",
          },
        ],
      });
      setAcceptedUpsells(prev => [...prev, "Silk Pillowcases"]);
      setUpsellTotal(prev => prev + 14.95);
    } catch (err) {
      console.error("[Downsell] Failed:", err);
    } finally {
      setIsUpsellProcessing(false);
      setFunnelStep("confirmation");
    }
  };

  // Decline downsell → go to confirmation and tell server to fulfill
  const handleDeclineDownsell = () => {
    declineUpsellMutation.mutate({ paymentIntentId });
    setFunnelStep("confirmation");
  };

  return (
    <div className="mt-3 space-y-4 animate-[fadeIn_0.3s_ease-out]">
      {/* ═══ STEP 1: Primary Upsell Offer ═══ */}
      {funnelStep === "upsell_1" && (
        <UpsellOffer1
          firstName={firstName}
          email={email}
          totalAmount={totalAmount}
          paymentIntentId={paymentIntentId}
          isProcessing={isUpsellProcessing}
          onAccept={handleAcceptUpsell1}
          onDecline={handleDeclineUpsell1}
        />
      )}

      {/* ═══ STEP 2: Downsell (only if primary declined) ═══ */}
      {funnelStep === "downsell_1" && (
        <DownsellOffer
          firstName={firstName}
          isProcessing={isUpsellProcessing}
          onAccept={handleAcceptDownsell}
          onDecline={handleDeclineDownsell}
        />
      )}

      {/* ═══ STEP 3: Final Confirmation ═══ */}
      {funnelStep === "confirmation" && (
        <FinalConfirmation
          firstName={firstName}
          email={email}
          totalAmount={totalAmount}
          paymentIntentId={paymentIntentId}
          acceptedUpsells={acceptedUpsells}
          upsellTotal={upsellTotal}
          onClose={onClose}
        />
      )}
    </div>
  );
}

/* ─── Countdown Timer Hook ─── */
function useCountdown(seconds: number) {
  const [timeLeft, setTimeLeft] = useState(seconds);
  useEffect(() => {
    if (timeLeft <= 0) return;
    const timer = setInterval(() => setTimeLeft(t => Math.max(0, t - 1)), 1000);
    return () => clearInterval(timer);
  }, [timeLeft]);
  const mins = Math.floor(timeLeft / 60);
  const secs = timeLeft % 60;
  return { timeLeft, display: `${mins}:${secs.toString().padStart(2, "0")}` };
}

