/* ═══════════════════════════════════════════════════════════
   MAIN COMPONENT
   ═══════════════════════════════════════════════════════════ */
export function InlineNativeCheckout({
  checkoutData,
  onPaymentComplete,
  onBack,
  orderBumps = [],
  bundleUpgrade,
  onBundleUpgrade,
  autoShowPayment: props_autoShowPayment = false,
}: InlineNativeCheckoutProps) {
  const { totalPrice, cartItems, fp, currencyCode, isUS } = checkoutData;

  // Single-flow state (no separate steps)
  const [email, setEmail] = useState("");
  const [address, setAddress] = useState<ShippingAddress | null>(null);
  const [currency, setCurrency] = useState(currencyCode || "usd");
  const [isProcessing, setIsProcessing] = useState(false);
  const [clientSecret, setClientSecret] = useState<string | null>(null);
  const [paymentIntentId, setPaymentIntentId] = useState<string | null>(null);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [showConfirmation, setShowConfirmation] = useState(false);
  const [isProcessingOrder, setIsProcessingOrder] = useState(false);
  const [addressSubmitted, setAddressSubmitted] = useState(false);
  const [isEditingAddress, setIsEditingAddress] = useState(false);
  const [selectedBumpIds, setSelectedBumpIds] = useState<Set<string>>(() => {
    const preChecked = new Set<string>();
    orderBumps.forEach((b) => { if (b.preChecked) preChecked.add(b.id); });
    return preChecked;
  });
  const [fbCheckoutTracked, setFbCheckoutTracked] = useState(false);

  const paymentSectionRef = useRef<HTMLDivElement>(null);

  // FB Pixel: InitiateCheckout on mount (first render of native checkout)
  useEffect(() => {
    if (!fbCheckoutTracked) {
      trackFBEvent("InitiateCheckout", {
        content_type: "product",
        value: totalPrice,
        currency: currencyCode?.toUpperCase() || "USD",
        num_items: cartItems.reduce((sum, i) => sum + i.quantity, 0),
      });
      setFbCheckoutTracked(true);
    }
  }, []);

  // Clear individual field errors
  const handleClearError = useCallback((field: string) => {
    setErrors((prev) => {
      if (!prev[field]) return prev;
      const next = { ...prev };
      delete next[field];
      return next;
    });
  }, []);

  // Toggle bump selection
  const handleToggleBump = useCallback((id: string) => {
    setSelectedBumpIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }, []);

  // Calculate total with bumps
  const bumpTotal = useMemo(() => {
    let total = 0;
    orderBumps.forEach((b) => {
      if (selectedBumpIds.has(b.id)) total += b.price;
    });
    return total;
  }, [orderBumps, selectedBumpIds]);

  const totalWithBumps = totalPrice + bumpTotal;

  // Sync currency
  useEffect(() => {
    if (currencyCode) setCurrency(currencyCode);
  }, [currencyCode]);

  // Stripe config
  const { data: stripeConfig } = trpc.checkout.getConfig.useQuery();
  const stripePromise = useMemo(() => {
    if (stripeConfig?.publishableKey) return loadStripe(stripeConfig.publishableKey);
    return null;
  }, [stripeConfig?.publishableKey]);

  // Create payment intent
  const createPaymentIntent = trpc.checkout.createPaymentIntent.useMutation({
    onSuccess: (data) => {
      setClientSecret(data.clientSecret);
      setPaymentIntentId(data.paymentIntentId);
      setAddressSubmitted(true);
      setIsEditingAddress(false);
      setIsProcessing(false);

      // FB Pixel: AddPaymentInfo — user clicked "Continue to Payment" and intent was created
      trackFBEvent("AddPaymentInfo", {
        content_type: "product",
        value: totalWithBumps,
        currency: currency?.toUpperCase() || "USD",
      });

      // Scroll payment into view
      setTimeout(() => {
        paymentSectionRef.current?.scrollIntoView({ behavior: "smooth", block: "center" });
      }, 200);
    },
    onError: (err) => {
      setErrors({ general: err.message });
      setIsProcessing(false);
    },
  });

  const handleCountryChange = useCallback((c: CountryOption) => {
    setCurrency(c.currency);
  }, []);

  // Validate + submit address → get payment intent
  const handleContinueToPayment = useCallback(() => {
    const newErrors: Record<string, string> = {};
    if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) newErrors.email = "Valid email required";
    if (!address?.name?.trim()) newErrors.name = "Name required";
    if (!address?.line1?.trim()) newErrors.line1 = "Address required";
    if (!address?.city?.trim()) newErrors.city = "City required";
    if (!address?.postalCode?.trim()) newErrors.postalCode = "Postal code required";
    const c = SUPPORTED_COUNTRIES.find((x) => x.code === (address?.country || "US"));
    if (c?.requiresState && !address?.state?.trim()) newErrors.state = "State required";
    setErrors(newErrors);
    if (Object.keys(newErrors).length > 0) return;

    setIsProcessing(true);
    const apiCartItems = cartItems.map((item) => ({
      name: item.name,
      size: item.size as "Standard" | "King",
      quantity: item.quantity,
      unitPrice: item.unitPrice,
      originalPrice: item.originalPrice,
      type: item.type as "pillow" | "pillowcase" | "eyemask" | "extra-pillow" | "insurance" | "gift",
    }));

    // Add selected bumps to cart items
    const bumpCartItems = orderBumps
      .filter((b) => selectedBumpIds.has(b.id))
      .map((b) => ({
        name: b.name,
        size: "Standard" as const,
        quantity: 1,
        unitPrice: b.price,
        originalPrice: b.originalPrice,
        type: "gift" as const,
      }));

    createPaymentIntent.mutate({
      email,
      customerName: address!.name,
      currency,
      cartItems: [...apiCartItems, ...bumpCartItems],
      shippingAddress: address!,
      visitorId: "native-checkout",
    });
  }, [email, address, cartItems, currency, createPaymentIntent, orderBumps, selectedBumpIds]);

  // Handle "Save" when editing address
  const handleSaveAddress = useCallback(() => {
    handleContinueToPayment();
  }, [handleContinueToPayment]);

  // Payment success — show processing loader first, then confirmation
  const handlePaymentSuccess = useCallback(
    (piId: string) => {
      setPaymentIntentId(piId);
      setIsProcessingOrder(true); // Show loader first
      onPaymentComplete?.(piId);
    },
    [onPaymentComplete]
  );

  // Called when the 3.2s processing loader completes
  const handleProcessingComplete = useCallback(() => {
    setIsProcessingOrder(false);
    setShowConfirmation(true);
  }, []);

  const handlePaymentError = useCallback((error: string) => {
    setErrors({ payment: error });
  }, []);

  // Stripe appearance — compact, matching brand
  const stripeAppearance = useMemo(
    () => ({
      theme: "stripe" as const,
      variables: {
        colorPrimary: "#424680",
        colorBackground: "#ffffff",
        colorText: "#1a1a1a",
        colorDanger: "#e63946",
        fontFamily: "'Inter', system-ui, -apple-system, sans-serif",
        borderRadius: "6px",
        spacingUnit: "3px",
      },
      rules: {
        ".Input": {
          border: "1px solid #e5e7eb",
          boxShadow: "none",
          padding: "10px 12px",
          fontSize: "14px",
        },
        ".Input:focus": {
          border: "1px solid #424680",
          boxShadow: "0 0 0 2px rgba(66, 70, 128, 0.12)",
        },
        ".Label": {
          fontSize: "11px",
          fontWeight: "500",
          textTransform: "uppercase" as const,
          letterSpacing: "0.04em",
          color: "#6b7280",
        },
        ".Tab": {
          border: "1px solid #e5e7eb",
          borderRadius: "6px",
        },
        ".Tab--selected": {
          border: "1px solid #424680",
          backgroundColor: "#f8f8ff",
        },
      },
    }),
    []
  );

  // ── Processing Loader (3.2s branded animation) ──
  if (isProcessingOrder && paymentIntentId) {
    return (
      <OrderProcessingLoader
        onComplete={handleProcessingComplete}
        customerName={address?.name || ""}
      />
    );
  }

  // ── Post-Purchase Confirmation + VSL ──
  if (showConfirmation && paymentIntentId) {
    return (
      <PostPurchaseView
        email={email}
        paymentIntentId={paymentIntentId}
        totalAmount={fp(totalWithBumps)}
        customerName={address?.name || ""}
        fp={fp}
        onClose={() => {
          setShowConfirmation(false);
          setClientSecret(null);
          setPaymentIntentId(null);
          setAddressSubmitted(false);
        }}
      />
    );
  }

  return (
    <div className="mt-3 space-y-3">
      {/* Secure Checkout Header */}
      <SecureCheckoutHeader onBack={onBack} />

      {/* General error */}
      {errors.general && (
        <div className="p-2.5 rounded-md bg-red-50 border border-red-200 text-xs text-red-700 flex items-start gap-2">
          <AlertCircle className="w-3.5 h-3.5 flex-shrink-0 mt-0.5" />
          {errors.general}
        </div>
      )}

      {/* ── Delivery Information Card ── */}
      <div className="bg-white rounded-xl border border-gray-200 p-4">
        <div className="flex items-center justify-between mb-3">
          <span className="text-xs font-semibold text-[#2d3058] uppercase tracking-wide">
            Delivery Information
          </span>
          {addressSubmitted && !isEditingAddress && (
            <div className="flex items-center gap-1.5 bg-green-50 border border-green-200 rounded-full px-2.5 py-1">
              <div className="w-3.5 h-3.5 rounded-full bg-green-500 flex items-center justify-center flex-shrink-0">
                <Check className="w-2.5 h-2.5 text-white" strokeWidth={3} />
              </div>
              <span className="text-[10px] font-semibold text-green-700 whitespace-nowrap">
                Free 2-3 Day Shipping Confirmed
              </span>
            </div>
          )}
        </div>

        {addressSubmitted && !isEditingAddress ? (
          /* Compact address summary — Edit opens form without collapsing payment */
          <div className="text-sm space-y-1">
            <div className="flex items-center justify-between">
              <span className="text-muted-foreground text-xs">Ship to</span>
              <button
                onClick={() => setIsEditingAddress(true)}
                className="flex items-center gap-1 text-[11px] text-[#424680] hover:underline font-medium"
              >
                <Pencil className="w-3 h-3" />
                Edit
              </button>
            </div>
            <p className="text-xs font-medium truncate">
              {address?.name} · {address?.line1}, {address?.city}{address?.state ? `, ${address.state}` : ""} {address?.postalCode}
            </p>
            <p className="text-xs text-muted-foreground">{email}</p>
          </div>
        ) : isEditingAddress ? (
          /* Edit mode — form with Save button, payment stays visible below */
          <div>
            <form autoComplete="on" method="post" action="#" onSubmit={(e) => { e.preventDefault(); handleSaveAddress(); }}>
              <CompactAddressForm
                address={address}
                email={email}
                onAddressChange={setAddress}
                onEmailChange={setEmail}
                detectedCountryCode={isUS ? "US" : undefined}
                errors={errors}
                onCountryChange={handleCountryChange}
                onClearError={handleClearError}
              />
              <div className="flex gap-2 mt-3">
                <button
                  type="submit"
                  disabled={isProcessing}
                  className="flex-1 bg-[#424680] hover:bg-[#363a6b] text-white font-medium py-2.5 rounded-full text-sm transition-colors flex items-center justify-center gap-1.5"
                >
                  {isProcessing ? (
                    <svg className="animate-spin h-4 w-4 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                      <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
                      <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z" />
                    </svg>
                  ) : (
                    <Check className="w-3.5 h-3.5" />
                  )}
                  Save Address
                </button>
                <button
                  type="button"
                  onClick={() => setIsEditingAddress(false)}
                  className="px-4 py-2.5 border border-gray-200 text-gray-600 font-medium rounded-full text-sm hover:bg-gray-50 transition-colors"
                >
                  Cancel
                </button>
              </div>
            </form>
          </div>
        ) : (
          /* Initial form — wrapped in <form> for browser autofill with CTA inside */
          <form autoComplete="on" method="post" action="#" onSubmit={(e) => { e.preventDefault(); handleContinueToPayment(); }}>
            <CompactAddressForm
              address={address}
              email={email}
              onAddressChange={setAddress}
              onEmailChange={setEmail}
              detectedCountryCode={isUS ? "US" : undefined}
              errors={errors}
              onCountryChange={handleCountryChange}
              onClearError={handleClearError}
            />

            {/* ── Order Bumps — Between delivery and payment ── */}
            {orderBumps.length > 0 && (
              <div className="mt-3">
                <CheckoutOrderBumps
                  bumps={orderBumps}
                  bundleUpgrade={bundleUpgrade}
                  selectedBumpIds={selectedBumpIds}
                  onToggleBump={handleToggleBump}
                  onAcceptUpgrade={onBundleUpgrade}
                  fp={fp}
                  currencyCode={currencyCode}
                />
              </div>
            )}

            {/* Continue to Payment CTA — inside form for proper autofill */}
            <button
              type="submit"
              disabled={isProcessing}
              className={`w-full mt-4 bg-[#e63946] hover:bg-[#d62839] text-white font-semibold py-3.5 rounded-full text-base transition-all flex items-center justify-center gap-2 ${
                isProcessing ? "opacity-80 cursor-wait" : "hover:shadow-lg hover:shadow-red-200/50 active:scale-[0.98]"
              }`}
            >
              {isProcessing ? (
                <>
                  <svg className="animate-spin h-4 w-4 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z" />
                  </svg>
                  <span>Preparing Payment...</span>
                </>
              ) : (
                <>
                  <Lock className="w-4 h-4" />
                  Continue to Payment — {fp(totalWithBumps)}
                </>
              )}
            </button>
          </form>
        )}
      </div>

      {/* ── Payment Section ── */}
      <div ref={paymentSectionRef}>
        {addressSubmitted && clientSecret && stripePromise ? (
          /* Payment form — appears after address is submitted */
          <div className="bg-white rounded-xl border border-gray-200 p-4">
            <div className="flex items-center gap-2 mb-3">
              <span className="text-xs font-semibold text-[#2d3058] uppercase tracking-wide">
                Payment
              </span>
            </div>
            <Elements
              stripe={stripePromise}
              options={{
                clientSecret,
                appearance: stripeAppearance,
                locale: "en",
              }}
            >
              <UnifiedPaymentForm
                onPaymentSuccess={handlePaymentSuccess}
                onPaymentError={handlePaymentError}
                isProcessing={isProcessing}
                setIsProcessing={setIsProcessing}
                totalAmount={fp(totalWithBumps)}
                customerEmail={email}
              />
            </Elements>
          </div>
        ) : null}
      </div>
    </div>
  );
}
