import { useEffect, useRef } from 'react';
import { X } from 'lucide-react';
import QuizModule from './QuizModule';
import { trackQuizStart, trackQuizAbandon } from '@/lib/ga4-tracking';

interface QuizModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export function QuizModal({ isOpen, onClose }: QuizModalProps) {
  const quizStartedRef = useRef(false);
  const quizCompletedRef = useRef(false);
  
  // Track quiz_start when modal opens
  useEffect(() => {
    if (isOpen && !quizStartedRef.current) {
      quizStartedRef.current = true;
      quizCompletedRef.current = false;
      // Determine source from current page
      const path = window.location.pathname;
      const source = path === '/' || path === '' ? 'homepage' : path.replace(/^\//, '').replace(/\//g, '_');
      trackQuizStart(source);
    }
    if (!isOpen) {
      quizStartedRef.current = false;
    }
  }, [isOpen]);
  
  // Handle close with abandon tracking
  const handleClose = () => {
    if (!quizCompletedRef.current) {
      // Quiz was abandoned — estimate step from DOM (quiz has 12 questions)
      trackQuizAbandon(0, 12); // Step 0 = unknown, will be overridden if we can detect
    }
    onClose();
  };
  
  // Prevent body scroll and preserve scroll position when modal is open
  useEffect(() => {
    if (isOpen) {
      const scrollY = window.scrollY;
      document.body.style.position = 'fixed';
      document.body.style.top = `-${scrollY}px`;
      document.body.style.width = '100%';
      document.body.style.overflow = 'hidden';
      
      return () => {
        document.body.style.position = '';
        document.body.style.top = '';
        document.body.style.width = '';
        document.body.style.overflow = '';
        window.scrollTo(0, scrollY);
      };
    }
  }, [isOpen]);
  
  if (!isOpen) return null;

  /**
   * Determine if the current page is a "product page" (ProductLandingTemplate / Home).
   * Product pages use the base `/` route or locale-prefixed root like `/uk-en/`.
   * Non-product pages are use-case pages (/side-sleeper-pillow) or framed stories (/5-star-hotel-comfort).
   * 
   * Logic: if the path (minus locale prefix) is `/` or a known product slug, redirect to base.
   * Otherwise (use-case pages like /side-sleeper-pillow), stay on the current page.
   */
  const isProductPage = (): boolean => {
    const path = window.location.pathname;
    // Strip locale prefix (e.g., /uk-en) if present
    const pathWithoutLocale = path.replace(/^\/[a-z]{2}-[a-z]{2}/, '');
    // Product page slugs that should redirect to base
    const productSlugs = [
      '/', '',
      '/down-alternative',
      '/down-pillow-restorative-alignment',
      '/hotel-quality-pillow',
      '/neck-pain-relief-pillow',
      '/valentine-gift',
      '/mothers-day-gift',
      '/fathers-day-gift',
      '/black-friday',
    ];
    return productSlugs.includes(pathWithoutLocale) || pathWithoutLocale === '';
  };

  /**
   * Get the locale prefix from the current URL (e.g., '/uk-en' from '/uk-en/some-page')
   */
  const getLocalePrefix = (): string => {
    const match = window.location.pathname.match(/^\/([a-z]{2}-[a-z]{2})/);
    return match ? `/${match[1]}` : '';
  };

  const handleComplete = (profile: any, score: number, tags: string[]) => {
    quizCompletedRef.current = true;
    console.log('Quiz completed:', profile, score);
    
    // Build query params for the result page
    const displayLabels = tags.map(t => t.replace(/_/g, ' ')).slice(0, 4);
    const labelsParam = encodeURIComponent(displayLabels.join(','));
    const tagsParam = encodeURIComponent(tags.join(','));
    const quizParams = `from=quiz&profile=${profile.slug}&score=${score}&tags=${tagsParam}&labels=${labelsParam}`;
    
    // Close modal first
    onClose();
    
    const localePrefix = getLocalePrefix();
    
    if (isProductPage()) {
      // Product pages: always redirect to the base page (/) with quiz results
      // Use full page reload to ensure proper scroll-to-top and state reset
      window.location.href = `${localePrefix}/?${quizParams}`;
    } else {
      // Non-product pages (use-case, framed story): stay on current page
      // Reload current page with quiz params appended
      const currentPath = window.location.pathname;
      window.location.href = `${currentPath}?${quizParams}`;
    }
  };

  return (
    <div 
      className="fixed inset-0 z-[9999] bg-black/50 backdrop-blur-sm flex items-center justify-center p-0 sm:p-4"
      role="dialog"
      aria-modal="true"
      aria-labelledby="quiz-modal-title"
      onClick={handleClose}
    >
      <div 
        className="w-full max-w-2xl max-h-[90vh] overflow-y-auto bg-white rounded-none sm:rounded-2xl shadow-2xl relative"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Close Button */}
        <button
          onClick={handleClose}
          className="absolute top-3 right-3 sm:top-4 sm:right-4 z-10 w-9 h-9 sm:w-10 sm:h-10 rounded-full bg-gray-100 hover:bg-gray-200 flex items-center justify-center transition-colors"
          aria-label="Close quiz"
        >
          <X className="w-4 h-4 sm:w-5 sm:h-5" />
        </button>

        {/* Content - Unified white background container wrapping quiz */}
        <div className="p-4 sm:p-6 md:p-8">
          <QuizModule onComplete={handleComplete} />
        </div>
      </div>
    </div>
  );
}
